"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { Chip } from "@/components/atoms/chips/Chip"

/** Props for {@link CourseTrialChip}. */
export interface CourseTrialChipProps {
    /**
     * The enrollment's paid flag. The chip renders ONLY when this is `false`
     * (a trial / "Trial" placeholder); a real/paid enrollment shows nothing
     * (mark the exception, not the norm).
     */
    isEnrolled: boolean
}

/**
 * Small "Trial" badge for an enrolled-course row ??? surfaces that a course is
 * still a trial (the learner has not enrolled/paid yet) while progress is still
 * tracked. Soft warning tone; self-hiding for paid courses. Shared by every
 * place that renders the joined-course list (dashboard / profile / settings).
 *
 * @param props - {@link CourseTrialChipProps}
 */
export const CourseTrialChip = ({ isEnrolled }: CourseTrialChipProps) => {
    const t = useTranslations()
    if (isEnrolled) {
        return null
    }
    return (
        <Chip tone="warning" text={t("course.trial")} />
    )
}

"use client"

import React from "react"
import { Link } from "@heroui/react"
import {
    useResolveRouteNavigation,
} from "./useResolveRouteNavigation"
/** Props for {@link EntityToken}. */
export interface EntityTokenProps {
    /**
     * Opaque global id of the entity ??? resolved to a route on click. Omit when
     * passing a direct {@link EntityTokenProps.href} instead.
     */
    globalId?: string | null
    /**
     * Direct (already-built, locale-prefixed) route to push on click ??? use when the
     * caller already knows the path (e.g. a course `displayId`), skipping the
     * resolve round-trip. Takes precedence over {@link EntityTokenProps.globalId}.
     */
    href?: string
    /** Token text (username / lesson title ???). */
    label: string
    /**
     * Render as a full-width left-rail row (truncated, hover bg) instead of an
     * inline accent link. Defaults to inline.
     */
    block?: boolean
}

/**
 * A clickable entity reference inside the feed (GitHub-style `<user>`/`<challenge>`
 * token). On click it asks the route index (`resolveRoute(globalId)`) where the
 * entity lives, then navigates ??? the dashboard has no course context, so the
 * server resolves the path. Renders as plain bold text when not routable.
 * @param props - the entity global id + label
 */
export const EntityToken = ({
    globalId,
    href,
    label,
    block = false}: EntityTokenProps) => {
    // resolve-and-navigate lives in a shared hook (also used by whole-row list items)
    const { onPress, pending, routable } = useResolveRouteNavigation({ globalId, href })

    // block (left-rail row): full-width, truncated, link-style ??? hover underlines the
    // label (like a <Link>), no block fill; flush (no px) so it aligns with the card edge.
    if (block) {
        return (
            <button
                type="button"
                disabled={!routable || pending}
                onClick={onPress}
                className={"truncate py-1 text-left text-sm text-muted transition-colors hover:text-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)] disabled:opacity-60"}
            >
                {label}
            </button>
        )
    }

    // unresolvable target ??? non-interactive bold text
    if (!routable) {
        return (
            <span className="font-semibold text-foreground">{label}</span>
        )
    }

    return (
        <Link
            onPress={onPress}
            isDisabled={pending}
            className={"font-semibold text-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)] disabled:opacity-60 text-sm"}
        >
            {label}
        </Link>
    )
}

"use client"

import React from "react"
import { Button, Input, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    FilePdfIcon,
    FileTextIcon,
} from "@phosphor-icons/react"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { CvExportFormat } from "@/modules/types/enums/cv-export-format"
import { useCvEditorToolbarStore } from "@/hooks/zustand/cvEditorToolbar/store"

/** Props for {@link CvEditorToolbarBar}. */
export type CvEditorToolbarBarProps = Record<string, never>
/**
 * The CV editor's toolbar, rendered as the global Navbar's BOTTOM LAYER (so it
 * reads as the navbar's second row ??? no divider between them; the Navbar owns
 * the single bottom border). Back link + editable CV name + Word/PDF export.
 *
 * Back link + editable CV name + a "Download .tex" download (client-side, the raw
 * LaTeX source) and the PDF export (compiled server-side via tectonic ??? Word
 * was dropped in the full-LaTeX pivot).
 *
 * A STABLE node (registered once via `useRegisterNavbarBottomLayer`): it reads
 * all live state + callbacks from {@link useCvEditorToolbarStore} ??? which
 * `CvEditorPage` keeps in sync ??? so re-renders never remount the name input (focus
 * is preserved as the user types). Carries no border / sticky / bg of its own.
 *
 * @param props - {@link CvEditorToolbarBarProps}
 */
export const CvEditorToolbarBar = () => {
    const t = useTranslations()
    const label = useCvEditorToolbarStore((state) => state.label)
    const canExport = useCvEditorToolbarStore((state) => state.canExport)
    const exportingFormat = useCvEditorToolbarStore((state) => state.exportingFormat)
    const onBack = useCvEditorToolbarStore((state) => state.onBack)
    const onLabelChange = useCvEditorToolbarStore((state) => state.onLabelChange)
    const onExport = useCvEditorToolbarStore((state) => state.onExport)
    const onDownloadTex = useCvEditorToolbarStore((state) => state.onDownloadTex)

    return (
        <div className={"flex w-full items-center justify-between gap-3 px-6 pb-3"}>
            <Box className="shrink-0">
                <BackLink target={t("cv.builder.galleryTarget")} onPress={onBack} />
            </Box>
            <TextField
                aria-label={t("cv.builder.nameLabel")}
                className="min-w-0 w-full max-w-sm"
            >
                <Input
                    value={label}
                    placeholder={t("cv.builder.namePlaceholder")}
                    onChange={(event) => onLabelChange(event.target.value)}
                />
            </TextField>
            <StackH gap={4} principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                classNames={["shrink-0"]} items={[
                    () => (
                        <Button
                            variant="secondary"
                            isDisabled={!canExport}
                            onPress={onDownloadTex}
                        >
                            <FileTextIcon aria-hidden className="size-5" />
                            {t("cv.builder.downloadTexCta")}
                        </Button>
                    ),
                    () => (
                        <Button
                            variant="primary"
                            isDisabled={!canExport || exportingFormat !== null}
                            onPress={() => onExport(CvExportFormat.Pdf)}
                        >
                            <FilePdfIcon aria-hidden className="size-5" />
                            {t("cv.builder.downloadCta")}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
} from "react"
import {
    Alert,
    Button,
    Chip,
    Label,
    ListBox,
    ScrollShadow,
    Select,
    Typography,
    cn,
} from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import {
    ArrowRightIcon,
    BriefcaseIcon,
    PaperclipIcon,
    SquaresFourIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { GradeModelDropdown, type GradeModelSelection } from "@/components/blocks/grading/GradeModelDropdown"
import { GradeCreditCaption } from "@/components/blocks/grading/GradeCreditCaption"
import { AiModelTask } from "@/modules/api/graphql/queries/query-ai-models"
import { pathConfig } from "@/resources/path"
import { useSystemAiAutoConfig } from "@/hooks/useSystemAiAutoConfig"
import { useRegisterNavbarBottomLayer } from "@/hooks/zustand/navbarBottomLayer/store"
import { useCvEditorToolbarStore } from "@/hooks/zustand/cvEditorToolbar/store"
import { useQueryMyCvBlocksSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCvBlocksSwr"
import { useQueryMyPickableCvAchievementsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyPickableCvAchievementsSwr"
import { useQueryAiModelsSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiModelsSwr"
import { useQueryMyAiSettingsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiSettingsSwr"
import { useQueryMyAiQuotaSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiQuotaSwr"
import { useMutateUpdateCvBlocksSwr } from "@/hooks/swr/api/graphql/mutations/useMutateUpdateCvBlocksSwr"
import { useMutateRenderCvBlocksSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRenderCvBlocksSwr"
import { useMutateRewriteCvBlockSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRewriteCvBlockSwr"
import { CvBlockType } from "@/modules/types/enums/cv-block-type"
import { CvExportFormat } from "@/modules/types/enums/cv-export-format"
import {
    CV_BLOCK_TYPE_DEFAULT_TITLE_EN,
    CV_BLOCK_TYPE_ORDER,
    CV_BLOCK_TYPE_REGISTRY,
} from "@/components/blocks/cv/BlockRegistry"
import {
    DEFAULT_CV_STYLE,
    type CvBlock,
    type CvBlockItemFields,
    type CvDocument,
    type CvFontScale,
    type CvLanguage,
    type CvTemplate,
} from "@/modules/types/entities/cv"
import { computeCvCompleteness } from "@/modules/utils/cv-completeness"
import { CvBlockStack } from "@/components/blocks/cv/CvBlocksWorkspace/CvBlockStack"
import { CvPdfPreview } from "@/components/blocks/cv/CvBlocksWorkspace/CvPdfPreview"
import { CvTexEditor } from "@/components/blocks/cv/CvBlocksWorkspace/CvTexEditor"
import { buildCvTexSource } from "@/components/blocks/cv/CvBlocksWorkspace/buildCvTexSource"
import {
    CV_FONTS,
    CV_GOOGLE_FONTS_HREF,
    fontFamilyOf,
} from "@/components/blocks/cv/CvBlocksWorkspace/CvHtmlDocument/fonts"
import { CvSplitFromTextModal } from "@/components/blocks/cv/CvBlocksWorkspace/CvSplitFromTextModal"
import { CvTailorToJobModal } from "@/components/blocks/cv/CvBlocksWorkspace/CvTailorToJobModal"
import { CvTemplateGalleryModal } from "@/components/blocks/cv/CvBlocksWorkspace/CvTemplateGalleryModal"
import { CvWorkspaceSkeleton } from "@/components/blocks/cv/CvBlocksWorkspace/CvWorkspaceSkeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import { CvEditorToolbarBar } from "./CvEditorToolbarBar"

/** Accent swatches the style rail offers. */
const ACCENT_OPTIONS: Array<string> = [
    "#E84393",
    "#2563EB",
    "#16A34A",
    "#EA580C",
    "#7C3AED",
    "#0F172A",
]

/** How long to wait after the last edit before autosaving. */
const AUTOSAVE_DEBOUNCE_MS = 1000

/** Which pane the mobile `Edit | Preview` toggle is showing. */
type MobilePane = "edit" | "preview"

/**
 * How the edit pane is authored: `"block"` = the block-by-block form (the
 * `.tex` is regenerated from the blocks); `"latex"` = raw `.tex` editing (the
 * user's hand-edited source wins). The compiled-PDF preview is the same in both.
 */
type WorkspaceMode = "block" | "latex"

/** Font-scale segments the style rail offers ("Font size"). */
const FONT_SCALE_VALUES: Array<CvFontScale> = ["sm", "md", "lg"]

/** CV-language segments the style rail offers ("CV language"). */
const LANGUAGE_VALUES: Array<CvLanguage> = ["vi", "en"]

/** Props for {@link CvEditorPage}. */
export interface CvEditorPageProps {
    /** `cv_blocks.id` of the document being edited (from the route param). */
    cvId: string
}

/**
 * The dedicated CV editor surface (route `/profile/cv/[cvId]`). A roomy
 * three-zone layout: a narrow left STYLE RAIL (font + accent), the block form
 * in the middle, and the instant HTML preview on the right. A top bar holds
 * the back link to the gallery + the export buttons (PDF via Puppeteer, Word
 * via html-to-docx). Autosaves the draft; the preview updates client-side the
 * moment a block changes.
 *
 * @param props - {@link CvEditorPageProps}
 */
export const CvEditorPage = ({ cvId }: CvEditorPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const documentsSwr = useQueryMyCvBlocksSwr()
    const activeDocument = documentsSwr.data?.find((doc) => doc.id === cvId)
    const [mobilePane, setMobilePane] = useState<MobilePane>("edit")
    const { trigger: updateDocument } = useMutateUpdateCvBlocksSwr()
    const { trigger: exportDocument } = useMutateRenderCvBlocksSwr()
    const { trigger: rewriteBlock } = useMutateRewriteCvBlockSwr()
    const [exportingFormat, setExportingFormat] = useState<CvExportFormat | null>(null)
    const [isSplitModalOpen, setIsSplitModalOpen] = useState(false)
    const [isTailorModalOpen, setIsTailorModalOpen] = useState(false)
    const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false)

    const pickableAchievementsSwr = useQueryMyPickableCvAchievementsSwr()
    const capstoneCount = pickableAchievementsSwr.data?.milestoneTaskAttempts.length ?? 0

    // AI model picker ("AI assistant") ??? drives both "AI rewrite" (per-block
    // rewrite) and "Tailor to job posting" (tailor-to-JD). Auto lane
    // (both null) omits the model from the mutations below.
    const aiModelsSwr = useQueryAiModelsSwr()
    const aiSettingsSwr = useQueryMyAiSettingsSwr()
    const aiQuotaSwr = useQueryMyAiQuotaSwr()
    const aiQuota = aiQuotaSwr.data
    const aiAutoConfig = useSystemAiAutoConfig()
    const gradeModels = aiModelsSwr.data?.aiModels?.data?.gradableModels ?? []
    const canPremium = aiSettingsSwr.data?.canPremium ?? false
    const [aiSelection, setAiSelection] = useState<GradeModelSelection>({ model: null, provider: null })

    const onUpgrade = useCallback(() => {
        router.push(`${pathConfig().locale(locale).profile().build()}/ai-subscription`)
    }, [locale, router])

    /** Local editable copy ??? the stack edits this; this component debounces the autosave. */
    const [draft, setDraft] = useState<CvDocument | undefined>(undefined)

    /** Block-edit vs raw-LaTeX-edit for the edit pane (the preview is compiled-PDF either way). */
    const [mode, setMode] = useState<WorkspaceMode>("block")
    /** Hand-edited `.tex` buffer ??? only authoritative in `"latex"` mode. Seeded on first switch. */
    const [texDraft, setTexDraft] = useState<string>("")

    useEffect(() => {
        setDraft(activeDocument)
    }, [activeDocument])

    /**
     * The CV's CURRENT `.tex` ??? regenerated from the blocks in block mode, or the
     * user's hand-edited buffer in LaTeX mode. Feeds the compiled-PDF preview, the
     * PDF export, and the "Download .tex" action.
     */
    const currentTex = useMemo(() => {
        if (!draft) {
            return ""
        }
        return mode === "latex" ? texDraft : buildCvTexSource(draft)
    }, [draft, mode, texDraft])

    const onModeChange = useCallback((next: WorkspaceMode) => {
        // Seed the hand-edit buffer the first time LaTeX mode opens: the persisted
        // `tex_source` if any, else the current block-generated `.tex`.
        if (next === "latex") {
            setTexDraft((prev) => (prev.length > 0
                ? prev
                : (draft?.texSource ?? (draft ? buildCvTexSource(draft) : ""))))
        }
        setMode(next)
    }, [draft])

    useEffect(() => {
        if (!draft) {
            return
        }
        const timer = setTimeout(() => {
            void updateDocument({
                id: draft.id,
                label: draft.label,
                blocks: draft.blocks,
                style: draft.style,
            })
        }, AUTOSAVE_DEBOUNCE_MS)
        return () => clearTimeout(timer)
    }, [draft, updateDocument])

    const onBackToGallery = useCallback(() => {
        router.push(pathConfig().locale(locale).profile().cv().build())
    }, [locale, router])

    const onOpenCourses = () => {
        router.push(pathConfig().locale(locale).course().build())
    }

    const onLabelChange = useCallback((label: string) => {
        setDraft((prev) => (prev ? { ...prev, label } : prev))
    }, [])

    const onBlocksChange = (blocks: Array<CvBlock>) => {
        setDraft((prev) => (prev ? { ...prev, blocks } : prev))
    }

    const onAddBlock = (type: CvBlockType) => {
        setDraft((prev) => {
            if (!prev) {
                return prev
            }
            // English CVs get an English default title; Vietnamese (default) keeps
            // the i18n title. Only affects the DEFAULT ??? the learner can still rename it.
            const title = prev.style.language === "en"
                ? CV_BLOCK_TYPE_DEFAULT_TITLE_EN[type]
                : t(CV_BLOCK_TYPE_REGISTRY[type].titleKey)
            const nextBlock: CvBlock = {
                id: crypto.randomUUID(),
                type,
                title,
                order: prev.blocks.length,
                items: [],
            }
            return { ...prev, blocks: [...prev.blocks, nextBlock] }
        })
    }

    const onFontChange = (font: string) => {
        setDraft((prev) => (prev ? { ...prev, style: { ...prev.style, font } } : prev))
    }

    const onAccentChange = (accent: string) => {
        setDraft((prev) => (prev ? { ...prev, style: { ...prev.style, accent } } : prev))
    }

    const onFontScaleChange = (fontScale: CvFontScale) => {
        setDraft((prev) => (prev ? { ...prev, style: { ...prev.style, fontScale } } : prev))
    }

    const onLanguageChange = (language: CvLanguage) => {
        setDraft((prev) => (prev ? { ...prev, style: { ...prev.style, language } } : prev))
    }

    const onTemplateChange = (template: CvTemplate) => {
        setDraft((prev) => (prev ? { ...prev, style: { ...prev.style, template } } : prev))
    }

    const onAiRewrite = async (block: CvBlock, itemId: string | undefined): Promise<CvBlockItemFields> => {
        const targetItem = itemId ? block.items.find((item) => item.id === itemId) : block.items[0]
        const result = await rewriteBlock({
            block,
            capstoneAttemptId: targetItem?.sourceRef,
            selectedModel: aiSelection.model,
            selectedModelProvider: aiSelection.provider,
        })
        const rewrittenBlock = result.data?.rewriteCvBlock?.data?.block
        if (!rewrittenBlock) {
            throw new Error("AI rewrite failed")
        }
        const rewrittenItem = itemId
            ? rewrittenBlock.items.find((item) => item.id === itemId)
            : rewrittenBlock.items[0]
        return rewrittenItem?.fields ?? {}
    }

    const onSplitBlocks = (blocks: Array<CvBlock>) => {
        setDraft((prev) => (prev ? { ...prev, blocks } : prev))
    }

    const onTailoredBlocks = (blocks: Array<CvBlock>) => {
        setDraft((prev) => (prev ? { ...prev, blocks } : prev))
    }

    const onExport = useCallback(async (format: CvExportFormat) => {
        if (!draft) {
            return
        }
        setExportingFormat(format)
        try {
            await updateDocument({
                id: draft.id,
                label: draft.label,
                blocks: draft.blocks,
                style: draft.style,
            })
            const result = await exportDocument({
                id: draft.id,
                tex: currentTex,
                format,
            })
            const url = result.data?.renderCvBlocks?.data?.url
            if (url) {
                window.open(url, "_blank")
            }
        } finally {
            setExportingFormat(null)
        }
    }, [draft, updateDocument, exportDocument, currentTex])

    /** Download the current `.tex` as a client-side file (no server round-trip). */
    const onDownloadTex = useCallback(() => {
        if (!draft) {
            return
        }
        const blob = new Blob([currentTex], { type: "text/x-tex" })
        const objectUrl = URL.createObjectURL(blob)
        const anchor = document.createElement("a")
        anchor.href = objectUrl
        anchor.download = `${draft.label || "cv"}.tex`
        document.body.appendChild(anchor)
        anchor.click()
        anchor.remove()
        URL.revokeObjectURL(objectUrl)
    }, [draft, currentTex])

    // Feed the toolbar (rendered as the Navbar's bottom layer) via a store, and
    // register a STABLE node once so the name input never remounts (keeps focus).
    const setToolbar = useCvEditorToolbarStore((state) => state.setToolbar)
    useEffect(() => {
        setToolbar({
            label: draft?.label ?? "",
            canExport: Boolean(draft),
            exportingFormat,
            onBack: onBackToGallery,
            onLabelChange,
            onExport,
            onDownloadTex,
        })
    }, [draft?.label, draft, exportingFormat, onBackToGallery, onLabelChange, onExport, onDownloadTex, setToolbar])
    const toolbarNode = useMemo(() => <CvEditorToolbarBar />, [])
    useRegisterNavbarBottomLayer(toolbarNode)

    const completeness = useMemo(
        () => (draft ? computeCvCompleteness(draft) : null),
        [draft],
    )

    const presentSingletonTypes = useMemo(
        () => new Set(
            (draft?.blocks ?? [])
                .filter((block) => CV_BLOCK_TYPE_REGISTRY[block.type].singleton)
                .map((block) => block.type),
        ),
        [draft?.blocks],
    )
    const addableTypes = CV_BLOCK_TYPE_ORDER.filter((type) => !presentSingletonTypes.has(type))

    const isLoading = documentsSwr.isLoading && !documentsSwr.data
    const isMissing = !documentsSwr.isLoading && !activeDocument

    return (
        <div className={"flex flex-col overflow-x-hidden"}>
            {/* Load all catalog Google fonts so any pick renders instantly in the
                preview (React 19 hoists this <link> into <head>). The toolbar
                (back + name + export) renders in the Navbar's bottom layer. */}
            <link rel="stylesheet" href={CV_GOOGLE_FONTS_HREF} />

            <AsyncContent
                isLoading={isLoading}
                skeleton={<Box principle="page-pad" className="p-6"
                    explain="Page chrome inset ??? not card-padding, because this pads the whole page rather than a nested card surface."><CvWorkspaceSkeleton /></Box>}
                isEmpty={isMissing}
                emptyContent={{
                    title: t("cv.builder.missingTitle"),
                    description: t("cv.builder.missingHint"),
                    onRetry: onBackToGallery,
                    retryLabel: t("cv.builder.galleryTarget"),
                }}
                error={documentsSwr.error}
                errorContent={{
                    title: t("cv.builder.errorTitle"),
                    onRetry: () => documentsSwr.mutate(),
                    retryLabel: t("cv.builder.retry"),
                }}
            >
                {/* Mobile mode switch ??? desktop shows all zones.
                    Retuned to page-pad (p-6) from held asymmetric px-6 pt-4. */}
                <Box principle="page-pad" className="p-6 @app-lg:hidden"
                    explain="Page chrome inset ??? not card-padding, because this pads the whole page rather than a nested card surface.">
                    <TabsCard
                        variant="primary"
                        leftTabs={{
                            selectedKey: mobilePane,
                            ariaLabel: t("cv.builder.mobilePaneAria"),
                            onSelectionChange: (key) => setMobilePane(String(key) as typeof mobilePane),
                            items: [
                                { key: "edit", label: t("cv.builder.editPane") },
                                { key: "preview", label: t("cv.builder.previewPane") },
                            ],
                        }}
                    />
                </Box>

                {/* Full-bleed shell ??? flush style SIDEBAR (border-r, viewport-tall,
                    drag-resizable on desktop) + content (blocks | preview), each an
                    independent scroll region. */}
                <div className="flex flex-col @app-lg:h-[calc(100dvh-7.5rem)] @app-lg:flex-row">
                    {/* Style sidebar ??? flush-left, full-height, docs-style. Resizable
                        (mirrors the learn-shell content rail); mobile stays full-width
                        (the JS-driven width + drag handle are desktop-only). */}
                    <ResizableRail
                        storageKey="starci.cv.editorSidebar.width"
                        defaultWidth={256}
                        minWidth={220}
                        maxWidth={420}
                        ariaLabel={t("cv.builder.resizeSidebarAria")}
                        className={cn(
                            // the resize handle IS the divider ??? no separate `border-r` (mirrors
                            // the learn-shell content rail, which has none either; adding one on
                            // top of the handle line reads as a doubled/thicker divider). The
                            // long content scrolls inside a ScrollShadow (fade edges) below ???
                            // the root just frames + carries the resize handle.
                            "relative flex flex-col border-b border-separator @max-app-lg:w-full! @app-lg:shrink-0 @app-lg:border-b-0",
                            "[&>[role=separator]]:max-lg:hidden",
                            mobilePane !== "edit" && "hidden @app-lg:flex",
                        )}
                    >
                        {/* Long style/config list ??? ScrollShadow (fade edges) on desktop
                            (rule: long rail ??? ScrollShadow, not bare overflow). Mobile flows
                            naturally in the page stack (no fixed-height scroll). */}
                        <ScrollShadow
                            hideScrollBar
                            className="@app-lg:min-h-0 @app-lg:flex-1 @app-lg:overflow-y-auto"
                        >
                            <Box principle="page-pad" className="flex min-h-full flex-col p-6"
                                explain="Page chrome inset ??? not card-padding, because this pads the whole page rather than a nested card surface.">
                                <Box principle="block-boundary" className="flex flex-1 flex-col gap-6"
                                    explain="Block-to-block spacing ??? not group-boundary, because this separates major blocks rather than nested section groups.">
                                    {/* Template ??? coarsest style lever, so it sits at the top.
                            Shows the CURRENT value and opens a picker (the thumbnail
                            gallery), rendered as `Button variant="tertiary"` ??? matching
                            the "AI assistant" picker below (both button-style pickers;
                            Font/Font size stay real `Select` fields). */}
                                    <StackV gap={4} principle="label-field"
                                        explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                        items={[
                                            () => <Label>{t("cv.builder.template.label")}</Label>,
                                            () => (
                                                <Button
                                                    variant="tertiary"
                                                    size="sm"
                                                    fullWidth
                                                    aria-label={t("cv.builder.template.label")}
                                                    onPress={() => setIsTemplateModalOpen(true)}
                                                >
                                                    <SquaresFourIcon aria-hidden className="size-4 shrink-0" />
                                                    <span className="min-w-0 flex-1 truncate text-left">
                                                        {t(`cv.builder.template.names.${draft?.style.template ?? "classic"}`)}
                                                    </span>
                                                </Button>
                                            ),
                                        ]} />

                                    <StackV gap={4} principle="label-field"
                                        explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                        items={[
                                            () => <Label>{t("cv.builder.fontLabel")}</Label>,
                                            () => (
                                                <Select.Root
                                                    selectedKey={draft?.style.font ?? DEFAULT_CV_STYLE.font}
                                                    onSelectionChange={(key) => {
                                                        if (key) {
                                                            onFontChange(String(key))
                                                        }
                                                    }}
                                                >
                                                    <Select.Trigger aria-label={t("cv.builder.fontLabel")}>
                                                        <Select.Value style={{ fontFamily: fontFamilyOf(draft?.style.font ?? DEFAULT_CV_STYLE.font) }} />
                                                        <Select.Indicator />
                                                    </Select.Trigger>
                                                    <Select.Popover>
                                                        <ListBox.Root aria-label={t("cv.builder.fontLabel")} items={CV_FONTS}>
                                                            {(font) => (
                                                                <ListBox.Item key={font.key} id={font.key} textValue={font.label} aria-label={font.label}>
                                                                    <span style={{ fontFamily: font.family }}>{font.label}</span>
                                                                </ListBox.Item>
                                                            )}
                                                        </ListBox.Root>
                                                    </Select.Popover>
                                                </Select.Root>
                                            ),
                                        ]} />
                                    <StackV gap={4} principle="label-field"
                                        explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                        items={[
                                            () => <Label>{t("cv.builder.accentLabel")}</Label>,
                                            () => (
                                                <Cluster
                                                    gap={3}
                                                    principle="chip-row"
                                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                    align="center"
                                                    items={ACCENT_OPTIONS.map((hex) => () => (
                                                        <button
                                                            key={hex}
                                                            type="button"
                                                            aria-label={hex}
                                                            aria-pressed={draft?.style.accent === hex}
                                                            onClick={() => onAccentChange(hex)}
                                                            style={{ backgroundColor: hex }}
                                                            className={cn(
                                                                "size-6 shrink-0 cursor-pointer rounded-full outline-none transition-transform focus-visible:ring-2 focus-visible:ring-accent",
                                                                draft?.style.accent === hex && "scale-110 ring-2 ring-accent ring-offset-2 ring-offset-surface",
                                                            )}
                                                        />
                                                    ))}
                                                />
                                            ),
                                        ]} />

                                    <StackV gap={4} principle="label-field"
                                        explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                        items={[
                                            () => <Label>{t("cv.builder.fontScaleLabel")}</Label>,
                                            () => (
                                                <Select.Root
                                                    selectedKey={draft?.style.fontScale ?? DEFAULT_CV_STYLE.fontScale ?? "md"}
                                                    onSelectionChange={(key) => {
                                                        if (key) {
                                                            onFontScaleChange(key as CvFontScale)
                                                        }
                                                    }}
                                                >
                                                    <Select.Trigger aria-label={t("cv.builder.fontScaleLabel")}>
                                                        <Select.Value />
                                                        <Select.Indicator />
                                                    </Select.Trigger>
                                                    <Select.Popover>
                                                        <ListBox.Root
                                                            aria-label={t("cv.builder.fontScaleLabel")}
                                                            items={FONT_SCALE_VALUES.map((value) => ({ value }))}
                                                        >
                                                            {(item) => (
                                                                <ListBox.Item
                                                                    key={item.value}
                                                                    id={item.value}
                                                                    textValue={t(`cv.builder.fontScale.${item.value}`)}
                                                                    aria-label={t(`cv.builder.fontScale.${item.value}`)}
                                                                >
                                                                    {t(`cv.builder.fontScale.${item.value}`)}
                                                                </ListBox.Item>
                                                            )}
                                                        </ListBox.Root>
                                                    </Select.Popover>
                                                </Select.Root>
                                            ),
                                        ]} />

                                    <StackV gap={4} principle="label-field"
                                        explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                        items={[
                                            () => <Label>{t("cv.builder.languageLabel")}</Label>,
                                            () => (
                                                <Select.Root
                                                    selectedKey={draft?.style.language ?? DEFAULT_CV_STYLE.language ?? "vi"}
                                                    onSelectionChange={(key) => {
                                                        if (key) {
                                                            onLanguageChange(key as CvLanguage)
                                                        }
                                                    }}
                                                >
                                                    <Select.Trigger aria-label={t("cv.builder.languageLabel")}>
                                                        <Select.Value />
                                                        <Select.Indicator />
                                                    </Select.Trigger>
                                                    <Select.Popover>
                                                        <ListBox.Root
                                                            aria-label={t("cv.builder.languageLabel")}
                                                            items={LANGUAGE_VALUES.map((value) => ({ value }))}
                                                        >
                                                            {(item) => (
                                                                <ListBox.Item
                                                                    key={item.value}
                                                                    id={item.value}
                                                                    textValue={t(`cv.builder.language.${item.value}`)}
                                                                    aria-label={t(`cv.builder.language.${item.value}`)}
                                                                >
                                                                    {t(`cv.builder.language.${item.value}`)}
                                                                </ListBox.Item>
                                                            )}
                                                        </ListBox.Root>
                                                    </Select.Popover>
                                                </Select.Root>
                                            ),
                                        ]} />

                                    {/* AI assistant ??? the model picker for "AI rewrite" rewrites,
                            rendered `isButton` (matches the "Template" picker above ??? both
                            button-style pickers; Font/Font size stay real `Select`
                            fields). Sits ABOVE "Quick access" (reviewer: AI assistant goes on top).
                            Credit caption = shared `GradeCreditCaption` (weekly pool, same
                            as every other AI surface ??? see canon
                            `ai-credit-caption-bound-to-picker-not-button.md`). */}
                                    <StackV gap={4} principle="label-field"
                                        explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                        items={[
                                            () => <Label>{t("cv.builder.aiAssistantLabel")}</Label>,
                                            () => (
                                                <GradeModelDropdown
                                                    isButton
                                                    isButtonFullWidth
                                                    models={gradeModels}
                                                    selection={aiSelection}
                                                    canPremium={canPremium}
                                                    showAutoLane
                                                    task={AiModelTask.CvGenerating}
                                                    onSelect={setAiSelection}
                                                    onUpgrade={onUpgrade}
                                                />
                                            ),
                                            () => (
                                                <GradeCreditCaption
                                                    creditUsage={aiQuota}
                                                    hasPinnedModel={aiSelection.model !== null}
                                                    autoCreditCost={aiAutoConfig?.creditCost}
                                                />
                                            ),
                                        ]} />

                                    {/* Quick access ??? both ingest entry points: paste an existing CV +
                            tailor to a job description (reviewer: both belong in quick access). */}
                                    <StackV gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Label>{t("cv.builder.quickAccessLabel")}</Label>,
                                            () => (
                                                <Button variant="tertiary" className="w-full justify-start" onPress={() => setIsSplitModalOpen(true)}>
                                                    <PaperclipIcon aria-hidden className="size-4 shrink-0" />
                                                    <span className="min-w-0 flex-1 truncate text-left">{t("cv.builder.splitEntryCta")}</span>
                                                </Button>
                                            ),
                                            () => (
                                                <Button
                                                    variant="tertiary"
                                                    className="w-full justify-start"
                                                    isDisabled={!draft}
                                                    onPress={() => setIsTailorModalOpen(true)}
                                                >
                                                    <BriefcaseIcon aria-hidden className="size-4 shrink-0" />
                                                    <span className="min-w-0 flex-1 truncate text-left">{t("cv.builder.tailorEntryCta")}</span>
                                                </Button>
                                            ),
                                        ]} />

                                    {/* Completeness meter ??? cheap client-derived score + a
                            one-line nudge toward the highest-impact missing item. */}
                                    {completeness ? (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => (
                                                    <StackH gap={3} principle="flex-action" justify="between" align="center"
                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                        items={[
                                                            () => <Label>{t("cv.builder.completeness.label")}</Label>,
                                                            () => (
                                                                <Typography type="body-xs" color="muted">
                                                                    {t("cv.builder.completeness.percent", { percent: completeness.percent })}
                                                                </Typography>
                                                            ),
                                                        ]} />
                                                ),
                                                () => (
                                                    <div className="h-1.5 w-full rounded-full bg-default">
                                                        <div
                                                            className="h-full rounded-full bg-accent transition-all"
                                                            style={{ width: `${completeness.percent}%` }}
                                                        />
                                                    </div>
                                                ),
                                                ...(completeness.nextHintKey ? [() => {
                                                    const hintKey = completeness.nextHintKey as string
                                                    return (
                                                        <Typography type="body-xs" color="muted">
                                                            {t(hintKey)}
                                                        </Typography>
                                                    )
                                                }] : []),
                                            ]} />
                                    ) : null}

                                    {/* Verified-project trust: a badge once earned, else an
                            ACCENT Alert card (course-funnel CTA ??? empty state pushes
                            to enrol/learn). The whole card IS the CTA (not just the
                            button), so the alert itself is accent-toned via `status`
                            (nested-in-sidebar tint ??? [[elements/alert]] ??3), not
                            warning. Vertical (button stacked in Content) to fit the
                            narrow sidebar. */}
                                    <Box principle="pin-bottom" className="mt-auto"
                                        explain="Pins this block to the bottom of its parent so the footer action stays visible under scrolling content.">
                                        {capstoneCount > 0 ? (
                                            <Chip className="bg-accent-soft text-accent-soft-foreground">
                                                <TrophyIcon aria-hidden className="size-4" />
                                                <Chip.Label>{t("cv.builder.trustBadge", { count: capstoneCount })}</Chip.Label>
                                            </Chip>
                                        ) : (
                                            <Alert status="accent" className="bg-accent-soft shadow-none">
                                                <Alert.Content>
                                                    <Alert.Title>{t("cv.builder.noCourseTitle")}</Alert.Title>
                                                    <Alert.Description>{t("cv.builder.noCourseHint")}</Alert.Description>
                                                    <Button
                                                        variant="primary"
                                                        size="sm"
                                                        className="mt-2 w-full"
                                                        onPress={onOpenCourses}
                                                    >
                                                        {t("cv.builder.noCourseCta")}
                                                        <ArrowRightIcon aria-hidden className="size-4" />
                                                    </Button>
                                                </Alert.Content>
                                            </Alert>
                                        )}
                                    </Box>
                                </Box>
                            </Box>
                        </ScrollShadow>
                    </ResizableRail>

                    {/* Content ??? edit pane (block form | raw LaTeX) | compiled-PDF preview,
                        each an independent scroll region. */}
                    <Box principle="page-pad" className="min-h-0 min-w-0 flex-1 p-6 @app-lg:overflow-hidden"
                        explain="Page chrome inset ??? not card-padding, because this pads the whole page rather than a nested card surface.">
                        <Grid
                            principle="block-boundary"
                            explain="Block-to-block spacing ??? not group-boundary, because this separates major blocks rather than nested section groups."
                            columns={{ base: 1, lg: 2 }}
                            items={[
                                {
                                    key: "edit",
                                    content: () => (
                                        <div className={cn("min-h-0", mobilePane !== "edit" && "hidden @app-lg:block")}>
                                            <StackV
                                                gap={4}
                                                principle="label-field"
                                                explain="Form label above its field ??? not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => (
                                                        <TabsCard
                                                            variant="primary"
                                                            size="sm"
                                                            leftTabs={{
                                                                selectedKey: mode,
                                                                ariaLabel: t("cv.builder.modeAria"),
                                                                onSelectionChange: (key) => onModeChange(String(key) as WorkspaceMode),
                                                                items: [
                                                                    { key: "block", label: t("cv.builder.modeBlock") },
                                                                    { key: "latex", label: t("cv.builder.modeLatex") },
                                                                ],
                                                            }}
                                                        />
                                                    ),
                                                    () => (
                                                        mode === "block" ? (
                                                            <ScrollShadow hideScrollBar className="min-h-0 flex-1 @app-lg:pr-1">
                                                                {draft ? (
                                                                    <CvBlockStack
                                                                        blocks={draft.blocks}
                                                                        onChange={onBlocksChange}
                                                                        addableTypes={addableTypes}
                                                                        onAddBlock={onAddBlock}
                                                                        onAiRewrite={onAiRewrite}
                                                                    />
                                                                ) : null}
                                                            </ScrollShadow>
                                                        ) : (
                                                            <div className="min-h-0 flex-1">
                                                                <CvTexEditor value={texDraft} onChange={setTexDraft} />
                                                            </div>
                                                        )
                                                    ),
                                                ]}
                                            />
                                        </div>
                                    ),
                                },
                                {
                                    key: "preview",
                                    content: () => (
                                        <div className={cn("min-h-0", mobilePane !== "preview" && "hidden @app-lg:block")}>
                                            {draft ? <CvPdfPreview cvId={draft.id} tex={currentTex} /> : null}
                                        </div>
                                    ),
                                },
                            ]}
                        />
                    </Box>
                </div>
            </AsyncContent>

            <CvSplitFromTextModal
                isOpen={isSplitModalOpen}
                onOpenChange={setIsSplitModalOpen}
                onSplit={onSplitBlocks}
            />

            <CvTailorToJobModal
                isOpen={isTailorModalOpen}
                onOpenChange={setIsTailorModalOpen}
                blocks={draft?.blocks ?? []}
                selectedModel={aiSelection.model}
                selectedModelProvider={aiSelection.provider}
                onTailored={onTailoredBlocks}
            />

            {draft ? (
                <CvTemplateGalleryModal
                    isOpen={isTemplateModalOpen}
                    onOpenChange={setIsTemplateModalOpen}
                    doc={draft}
                    onSelect={onTemplateChange}
                />
            ) : null}
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { TrashIcon } from "@phosphor-icons/react"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCardPlaceholder } from "@/components/composites/cards/SurfaceCard"
import { MediaCard } from "@/components/blocks/cards/MediaCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Button } from "@/components/atoms/buttons/Button"
import { ChoiceSwitch } from "@/components/atoms/forms"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import type { CvDocument } from "@/modules/types/entities/cv"
import { CvHtmlDocument } from "@/components/blocks/cv/CvBlocksWorkspace/CvHtmlDocument"

/**
 * `_CvGallery` ??? the SRC TWIN, presentational half of the CvGalleryPage gallery block
 * (see `tiers/split.md`): typed props, already resolved; no fetch/store/i18n
 * (that's the connected half, `./index.tsx`). Renders the user's CvGalleryPage documents
 * as live scaled thumbnails; a click opens the dedicated editor. Layout:
 * optional {@link PageHeader} (standalone-page context only, gated on
 * `breadcrumb`) above a state switch ??? error ??? {@link AsyncContentError},
 * settled-empty ??? {@link AsyncContentEmpty}, otherwise the responsive card
 * grid (one {@link SurfaceCardPlaceholder} "create new" tile trailing the
 * real documents).
 */

/** How the open-editor overlay + delete/public-toggle row reads on one CvGalleryPage card. */
export interface CvGalleryDocument {
    /** Stable id ??? React key, delete/toggle targets. */
    id: string
    /** Already-resolved display label (the connected file falls back to "Untitled N"). */
    label: string
    /** Full block/style payload ??? feeds the scaled live thumbnail preview. */
    doc: CvDocument
    /** Whether this is the user's ONE public CvGalleryPage (single-public-per-user, BE-enforced). */
    isPublic: boolean
    /** `true` while this card's own public-toggle mutation is in flight. */
    isTogglingPublic: boolean
    /** Accessible name for the cover press target ??? already interpolated with the label. */
    editAriaLabel: string
    /** Opens this CvGalleryPage in the editor. */
    onOpen: () => void
    /** Removes this CvGalleryPage. */
    onDelete: () => void
    /** Flags/unflags this CvGalleryPage as the public one. */
    onTogglePublic: (isPublic: boolean) => void
}

/** All display text, already localized by the connected {@link CvGallery}; a story passes i18n keys. */
export interface CvGalleryLabels {
    /** Page title ??? only shown when {@link CvGalleryProps.breadcrumb} is passed. */
    pageTitle: string
    /** Page description under the title. */
    pageDescription: string
    /** Hover-reveal CTA pill printed over a card's thumbnail. */
    openEditor: string
    /** Accessible name for the per-card delete button. */
    deleteCta: string
    /** Label beside the per-card public-toggle switch. */
    publicToggle: string
    /** Hint line shown under a card's switch row while it IS the public CvGalleryPage. */
    publicHint: string
    /** Label on the trailing "create new" dashed tile. */
    createCta: string
    emptyTitle: string
    emptyHint: string
    /** Secondary link out of the empty state, toward the learner's courses. */
    emptyCoursesLinkCta: string
    /** Primary empty-state action label (same handler as the dashed tile). */
    createFirst: string
    errorTitle: string
    retry: string
}

/** Props for {@link _CvGallery} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface CvGalleryProps {
    /** Breadcrumb row rendered above the title (standalone page context); omitted ??? no header at all. */
    breadcrumb?: ReactNode
    /** First load, nothing in hand ??? the grid shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero documents ??? the empty state. */
    isEmpty?: boolean
    /** Truthy ??? the error message (beats loading + empty). */
    error?: unknown
    /** Retry the failed fetch. */
    onRetry?: () => void
    /** The CvGalleryPage documents, in display order. */
    documents: Array<CvGalleryDocument>
    /** Creates a new CvGalleryPage ??? the dashed tile's press handler AND the empty state's primary action. */
    onCreate: () => void
    /** `true` while the create mutation is in flight ??? disables the dashed tile. */
    isCreating?: boolean
    /** Courses browse link ??? the empty state's secondary action. */
    coursesHref: string
    labels: CvGalleryLabels
}

/** How many placeholder tiles the loading grid shows ??? mirrors the real grid's usual row. */
const SKELETON_TILE_COUNT = 3

const CvGalleryCardCover = ({ item, labels }: CvGalleryCardCoverProps) => (
    <button
        type="button"
        onClick={item.onOpen}
        aria-label={item.editAriaLabel}
        className="group relative block h-52 w-full cursor-pointer overflow-hidden bg-white outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent"
    >
        <Box
            aria-hidden
            className="pointer-events-none absolute inset-0"
            style={{ transform: "scale(0.42)", transformOrigin: "top left", width: "238%" }}
        >
            <CvHtmlDocument doc={item.doc} />
        </Box>
        <Box
            as="span"
            className="absolute inset-0 flex items-end justify-center bg-foreground/0 pb-3 opacity-0 transition-opacity group-hover:bg-foreground/5 group-hover:opacity-100"
        >
            <Box as="span" principle="pill-pad" className="rounded-full bg-accent px-4 py-2 text-sm text-accent-foreground"
                explain="Pill/chip inset ??? not control-pad, because this pads a compact badge shape rather than a form control.">
                {labels.openEditor}
            </Box>
        </Box>
    </button>
)

const CvGalleryCardFooter = ({ item, labels }: CvGalleryCardFooterProps) => (
    <StackV
        gap={3}
        principle="sibling-stack"
        explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="flex-action"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    justify="between"
                    items={[
                        () => (
                            <ChoiceSwitch
                                isSelected={item.isPublic}
                                isDisabled={item.isTogglingPublic}
                                onValueChange={item.onTogglePublic}
                                label={labels.publicToggle}
                            />
                        ),
                        () => (
                            <Button
                                isIconOnly
                                size="sm"
                                variant="ghost"
                                ariaLabel={labels.deleteCta}
                                prefixIcon={TrashIcon}
                                onPress={item.onDelete}
                            />
                        ),
                    ]}
                />
            ),
            ...(item.isPublic ? [() => (
                <Typography size="xs" color="muted" text={labels.publicHint} />
            )] : []),
        ]}
    />
)

/**
 * One CvGalleryPage card ??? a scaled live thumbnail that opens the editor, plus a
 * public-toggle switch and a delete button in the footer.
 */
const CvGalleryCard = ({ item, labels }: CvGalleryCardProps) => (
    <MediaCard
        cover={() => <CvGalleryCardCover item={item} labels={labels} />}
        title={item.label}
        footer={() => <CvGalleryCardFooter item={item} labels={labels} />}
    />
)

/** One dashed "add new" tile mirroring {@link SKELETON_TILE_COUNT} placeholder cards while loading. */
const SkeletonTile = () => <Box className="h-[19rem] rounded-3xl border border-default bg-surface" />

/**
 * The CvGalleryPage GALLERY (presentational) ??? the profile `?tab=cv` surface (and the standalone
 * `/profile/cv` page). See {@link CvGalleryProps} for the full state contract; the
 * connected `./index.tsx` owns the fetch, the mutations, and every `t()` call.
 *
 * @param props - {@link CvGalleryProps}
 */
export const _CvGallery = ({
    breadcrumb,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    documents,
    onCreate,
    isCreating = false,
    coursesHref,
    labels,
}: CvGalleryProps) => {
    // The empty state's own action slot: the same "create" handler as the dashed
    // tile, plus a secondary link out to the courses catalog ??? `AsyncContentEmpty`'s
    // `description` is a plain string (COMPOSITE-8), so the courses link can no
    // longer live INSIDE that sentence the way it used to; it now sits as its own
    // line below the primary button instead (missingVocabulary).
    const emptyAction: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
            align="center"
            items={[
                () => <Button label={labels.createFirst} variant="tertiary" size="sm" onPress={onCreate} />,
                () => <Typography size="sm" isLink href={coursesHref} text={labels.emptyCoursesLinkCta} />,
            ]}
        />
    )

    const gridItems: Array<GridItem> = isSkeleton
        ? Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
            key: `skeleton-${index}`,
            content: SkeletonTile,
        }))
        : [
            ...documents.map((item): GridItem => ({
                key: item.id,
                content: () => <CvGalleryCard item={item} labels={labels} />,
            })),
            {
                key: "__create",
                content: () => (
                    <SurfaceCardPlaceholder
                        label={labels.createCta}
                        onPress={onCreate}
                        isDisabled={isCreating}
                    />
                ),
            },
        ]

    let body: ReactNode
    if (error) {
        body = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        body = <AsyncContentEmpty title={labels.emptyTitle} description={labels.emptyHint} action={emptyAction} />
    } else {
        body = <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="block-boundary" explain="Block-to-block spacing ??? not group-boundary, because this separates major blocks rather than nested section groups." items={gridItems} />
    }

    return (
        <StackV
            gap={7}
            principle="layout-split"
            explain="Major layout split ??? not block-boundary, because this separates primary page regions rather than adjacent blocks."
            identity={{ tier: "block", component: "CvGallery" }}
            items={[
                ...(breadcrumb ? [() => (
                    <PageHeader
                        breadcrumb={breadcrumb}
                        title={labels.pageTitle}
                        description={labels.pageDescription}
                    />
                )] : []),
                () => body,
            ]}
        />
    )
}

