import React from "react"
import { CardsIcon as LayersIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import type { SkeletonProps } from "@/components/frames/_slot"
import { Box } from "@/components/frames/Box"
import { Split } from "@/components/frames/Split"

/** Already-localized text for {@link _FlashcardReview}; the connected `FlashcardReview` interpolates `dueCount`. */
export interface FlashcardReviewLabels {
    /** "N flashcards due today" row label. */
    due: string
    /** CTA button label, e.g. "Review 3". */
    startWithCount: string
}

/** Props for {@link _FlashcardReview} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewProps {
    /** First load, nothing in hand ??? the row shimmers in place (co-located). Owned by the connected `FlashcardReview`. */
    isSkeleton?: boolean
    /**
     * Settled with nothing to nudge about ??? zero cards due, or the fetch failed ??? so
     * the widget self-hides. The two are folded together deliberately: this SECONDARY
     * widget has no error message of its own, the same self-hide contract the old
     * `AsyncContent` had whenever `errorContent`/`emptyContent` were left unpassed.
     */
    isEmpty?: boolean
    /** Navigates into the dedicated review page. */
    onStartReview?: () => void
    labels: FlashcardReviewLabels
}

/**
 * Centre-column "flashcards due today" nudge ??? the presentational half of
 * {@link FlashcardReview}. Renders ONE row (icon + due-count label <-> "start
 * review" CTA), with `isSkeleton` threaded to both sides of the {@link Split}
 * so the shimmer mirrors the loaded shape (loading-and-skeleton.md).
 * Settled-and-empty (or a failed fetch) self-hides instead of showing a
 * message ??? this is a SECONDARY nudge, not a region with its own empty/error
 * voice. See `tiers/split.md` ??? the connected `FlashcardReview` owns the fetch
 * and resolves i18n.
 *
 * @param props - {@link FlashcardReviewProps}
 */
export const _FlashcardReview = ({
    isSkeleton = false,
    isEmpty = false,
    onStartReview,
    labels,
}: FlashcardReviewProps) => {
    // settled (not skeleton) + nothing to show ??? self-hide (no error/empty voice for this nudge)
    if (!isSkeleton && isEmpty) {
        return null
    }
    return (
        <Box principle="cell-pad" className="p-3"
            explain="Tight cell inset ??? not card-padding, because this sits inside a dense table or list cell rather than a card body."
            identity={{ tier: "block", component: "FlashcardReview" }}>
            <Split
                gap={3}
                isSkeleton={isSkeleton}
                start={({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        size="sm"
                        weight="medium"
                        prefixIcon={LayersIcon}
                        truncate
                        text={labels.due}
                        isSkeleton={isSkeleton}
                    />
                )}
                end={({ isSkeleton }: SkeletonProps) => (
                    <Button
                        variant="primary"
                        size="sm"
                        label={labels.startWithCount}
                        onPress={onStartReview}
                        isSkeleton={isSkeleton}
                    />
                )}
            />
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import {
    LeaderboardListCard,
    LeaderboardRow,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import type { QueryMyLeagueData } from "@/modules/api/graphql/queries/types/league"

/** How many top-of-cohort rows to show before truncating (no inner scroll). */
const TOP_ROWS = 5

/** Props for {@link LeagueCardContent}. */
export interface LeagueCardContentProps {
    /** The resolved (non-null) weekly-league standing ??? supplied by the container. */
    data: QueryMyLeagueData
    /** Kept for API compatibility with the container; the card is always framed now. */
    framed?: boolean
}

/**
 * DashboardPage "Weekly League" card ??? maps the resolved weekly-league data into the shared
 * {@link LeaderboardListCard} (standing header with a rank-driven medal/cup badge, then
 * the top cohort as a medal-ranked list with a rank-movement caret per row). Renders
 * identically to the global {@link import("../../TopLearners").TopLearners} card; only
 * the trailing slot (caret vs follow) differs (instructor's call, 2026-07-17, "two identical sections").
 *
 * @param props - {@link LeagueCardContentProps}
 */
export const LeagueCardContent = ({
    data}: LeagueCardContentProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const me = useAppSelector((state) => state.user.user)

    /** Open the full leaderboard/league page (see-more link in the card header). */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    /** Hours/days left until the weekly reset (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            const remaining = Math.max(0, new Date(data.weekEndAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [data],
    )

    const total = data.entries.length
    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    const myEntry = me?.username
        ? data.entries.find((entry) => entry.username === me.username)
        : undefined
    const myPercent = myEntry ? Math.max(1, Math.ceil((myEntry.rank / total) * 100)) : null

    // top slice INCLUDING the viewer in place; a pinned self-row follows when the
    // viewer sits below it.
    const topRows = data.entries.slice(0, TOP_ROWS)
    const viewerInTop = myEntry
        ? topRows.some((entry) => entry.userGlobalId === myEntry.userGlobalId)
        : true
    const showSelfRow = Boolean(myEntry) && !viewerInTop
    const hiddenBetween = showSelfRow && myEntry
        ? Math.max(0, myEntry.rank - topRows.length - 1)
        : 0

    /** Map a cohort entry ??? a normalised {@link LeaderboardRow} (caret trailing + movement band). */
    const toRow = (entry: typeof data.entries[number]): LeaderboardRow => {
        // band = weekly rank MOVEMENT (mirrors the ?????? `RankDeltaCaret`), NOT the cohort
        // promote/demote zone ??? a per-row signal that ALWAYS shows (no cohort-size gate,
        // so a small seed cohort still renders it): climbed ??? success, dropped ??? danger,
        // unchanged / no last-week baseline ??? no band (instructor's call, 2026-07-17: the DashboardPage
        // preview always shows it; unlike the /league page, which uses the promote/demote zone instead).
        const delta = entry.rankDelta ?? 0
        return {
            key: entry.userGlobalId,
            rank: entry.rank,
            username: entry.username,
            avatar: entry.avatar,
            valueLabel: t("DashboardPage.league.points", { count: entry.weekPoints }),
            isMe: isMine(entry.username),
            profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
            trailing: <RankDeltaCaret delta={entry.rankDelta} className="w-8 justify-end" />,
            verdict: delta !== 0
                ? { enable: true, variant: delta > 0 ? "success" : "danger" }
                : undefined,
        }
    }

    return (
        <LeaderboardListCard
            title={t("DashboardPage.league.title")}
            onSeeMore={onSeeMore}
            seeMoreLabel={t("DashboardPage.league.seeMore")}
            standing={myEntry && myPercent !== null ? {
                rank: myEntry.rank,
                primary: t("DashboardPage.myProfile.rankLine", {
                    rank: myEntry.rank,
                    percent: myPercent,
                }),
                secondary: (
                    <>
                        {t("DashboardPage.league.points", { count: myEntry.weekPoints })}
                        {` ?? ${t("DashboardPage.league.resetIn", {
                            days: countdown.days,
                            hours: countdown.hours,
                        })}`}
                    </>
                ),
            } : undefined}
            rows={topRows.map(toRow)}
            selfRow={showSelfRow && myEntry ? toRow(myEntry) : undefined}
            ellipsisLabel={hiddenBetween > 0
                ? t("DashboardPage.league.othersCount", { count: hiddenBetween })
                : undefined}
            meLabel={t("DashboardPage.league.you")}
        />
    )
}

"use client"

import React from "react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import {
    SurfaceListCard,
    SurfaceListCardItem,
} from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import {
    LeaderboardListCard,
    type LeaderboardRow,
    type LeaderboardStanding,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import { StackH, StackV } from "@/components/frames/Stack"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Number of placeholder cohort rows the co-located skeleton shows (mirrors the capped top rows). */
const SKELETON_ROWS = 5

/**
 * One resolved cohort entry, already mapped + translated by the connected {@link
 * import("./index").LeagueCard} ??? the presentational half turns it into a {@link LeaderboardRow}.
 */
export interface LeagueCardEntry {
    /** React key + stable id. */
    userGlobalId: string
    /** 1-based rank ??? ???3 renders a place medal, else the number. */
    rank: number
    /** Display username (null ??? dash). */
    username: string | null
    /** Avatar URL (null ??? generated fallback). */
    avatar?: string | null
    /** Rank movement vs last week (mirrors the ?????? {@link RankDeltaCaret}). */
    rankDelta: number | null
    /** True ??? highlight as the viewer (accent name + `meLabel` suffix). */
    isMe: boolean
    /** Profile link target. */
    profileHref: string
    /** Already-translated "N pts" label for this entry. */
    pointsLabel: string
}

/** Props for {@link _LeagueCard} ??? presentational; all data/text resolved, no fetch/store/i18n. */
export interface LeagueCardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand ??? the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no cohort placement ??? the empty message. */
    isEmpty?: boolean
    /**
     * Kept for API compatibility with the container; the card is always framed
     * (a `LabeledCard`, via {@link LeaderboardListCard}) now.
     */
    framed?: boolean
    /** League title (already translated). */
    title: string
    /**
     * Help text for the title's tooltip (already translated) ??? currently unused: the
     * label row has no slot for a decoration once `label` became plain text. Kept for
     * API compatibility until a real "labelAdornment" slot exists.
     */
    titleHelp: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label (already translated). */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). Text pre-resolved. */
    standing?: LeaderboardStanding
    /** Top-of-cohort entries (already sliced by the container). */
    entries?: Array<LeagueCardEntry>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfEntry?: LeagueCardEntry
    /** Ellipsis label above the pinned self-row (already translated). */
    ellipsisLabel?: string
    /** "You" suffix appended to the viewer's own row name (already translated). */
    meLabel?: string
    /** Empty-state title (already translated). */
    emptyTitle: string
    /** Empty-state description (already translated). */
    emptyDescription: string
}

/** Map one resolved {@link LeagueCardEntry} ??? a {@link LeaderboardRow} (caret trailing + movement band). */
const toRow = (entry: LeagueCardEntry): LeaderboardRow => ({
    key: entry.userGlobalId,
    rank: entry.rank,
    username: entry.username,
    avatar: entry.avatar,
    valueLabel: entry.pointsLabel,
    isMe: entry.isMe,
    profileHref: entry.profileHref,
    trailing: <RankDeltaCaret delta={entry.rankDelta} className="w-8 justify-end" />,
    verdict: entry.rankDelta
        ? { enable: true, variant: entry.rankDelta > 0 ? "success" : "danger" }
        : undefined,
})

/**
 * DashboardPage "Weekly League" card ??? the presentational half of {@link import("./index").LeagueCard}.
 * Renders identically to the global {@link import("../TopLearners").TopLearners} card through the
 * shared {@link LeaderboardListCard}; only the trailing slot (caret vs follow) differs (instructor's
 * call, 2026-07-17, "two identical sections").
 *
 * {@link LeaderboardListCard} takes no `isSkeleton` of its own (it owns the label + standing header
 * + row list as one opaque block), so the LOADING branch mirrors its exact structure by hand, right
 * at this call site ??? the same `LabeledCard` label, standing header, and bordered `SurfaceListCard`
 * rows, with `Skeleton.*` swapped in for every content node (`loading-and-skeleton.md` ??3/??6). This
 * is co-located (one file, one call site), not a separate skeleton component to keep in sync.
 *
 * @param props - {@link LeagueCardProps}
 */
export const _LeagueCard = ({
    isSkeleton = false,
    isEmpty = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    entries = [],
    selfEntry,
    ellipsisLabel,
    meLabel,
    emptyTitle,
    emptyDescription,
}: LeagueCardProps) => {
    // settled with no cohort placement (BLOCK-8) ??? translated empty state (join hint), not self-hide
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={emptyTitle} description={emptyDescription} />
    }

    if (isSkeleton) {
        return (
            <LabeledCard

                // `label` is plain text now (never a built element), and `title` is already
                // known statically (translated up front, not fetched) ??? showing it for real
                // instead of shimmering it is strictly more correct, not just a workaround.
                label={title}
            >
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Skeleton standing header and cohort rows are peer sections in one league card ??? not block-boundary."
                    items={[
                        () => (
                            <StackH gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center" items={[
                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                    () => (
                                        <StackV gap={2} principle="title-subtitle"
                                            explain="Title over supporting line ??? not label-field, because neither line is a form control label."
                                            classNames={["min-w-0", "flex-1"]} items={[
                                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                            ]} />
                                    ),
                                ]} />
                        ),
                        () => (
                            <SurfaceListCard bordered>
                                {Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                                    <SurfaceListCardItem key={index}>
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                                () => <Skeleton.Avatar size="sm" />,
                                                () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                                () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                                () => <Skeleton className="h-4 w-8 shrink-0 rounded-sm" />,
                                            ]} />
                                    </SurfaceListCardItem>
                                ))}
                            </SurfaceListCard>
                        ),
                    ]}
                />
            </LabeledCard>
        )
    }

    return (
        <LeaderboardListCard

            // `title` forwards into `LabeledCard.label`, plain text now (never a built
            // element) ??? the `InfoTooltip` decoration has no slot to ride any more
            // (mirrors the same drop in `LeagueCardContent`); `titleHelp` is unused here
            // pending a real "labelAdornment"-style slot on `LabeledCard`.
            title={title}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            standing={standing}
            rows={entries.map(toRow)}
            selfRow={selfEntry ? toRow(selfEntry) : undefined}
            ellipsisLabel={ellipsisLabel}
            meLabel={meLabel}
        />
    )
}

"use client"

import React from "react"
import {
    Icon,
} from "@iconify/react"
import {
    BadgeImage,
} from "@/components/blocks/identity/BadgeImage"
import { StackH } from "@/components/frames/Stack"

/**
 * Weekly-league tiers, lowest ??? highest. Mirrors the backend `LeagueTier` enum.
 * Names are picked so each maps to a *distinct, multicolor* `fluent-emoji-flat`
 * icon (medals ??? medal ??? gem ??? trophy ??? crown), escalating prestige.
 */
export enum LeagueTier {
    /** Entry tier. */
    Bronze = "bronze",
    /** Second tier. */
    Silver = "silver",
    /** Third tier. */
    Gold = "gold",
    /** Fourth tier. */
    Platinum = "platinum",
    /** Fifth tier. */
    Diamond = "diamond",
    /** Sixth tier. */
    Champion = "champion",
    /** Top tier. */
    Legend = "legend",
}

/**
 * Per-tier `fluent-emoji-flat` icon name (multicolor, no recolor needed) +
 * display label. The Iconify set ships gold/silver/bronze medals natively, so the
 * tier ladder reads as real metal/gem/crown art instead of one recolored shape.
 */
interface TierVisual {
    /** Iconify icon id (`fluent-emoji-flat:*`). */
    icon: string
    /** Human label shown next to the badge. */
    label: string
}

/** Tier ??? icon + label map. */
const TIER_VISUAL: Record<LeagueTier, TierVisual> = {
    [LeagueTier.Bronze]: {
        icon: "fluent-emoji-flat:3rd-place-medal",
        label: "Bronze",
    },
    [LeagueTier.Silver]: {
        icon: "fluent-emoji-flat:2nd-place-medal",
        label: "Silver",
    },
    [LeagueTier.Gold]: {
        icon: "fluent-emoji-flat:1st-place-medal",
        label: "Gold",
    },
    [LeagueTier.Platinum]: {
        icon: "fluent-emoji-flat:sports-medal",
        label: "Platinum",
    },
    [LeagueTier.Diamond]: {
        icon: "fluent-emoji-flat:gem-stone",
        label: "Diamond",
    },
    [LeagueTier.Champion]: {
        icon: "fluent-emoji-flat:trophy",
        label: "Champion",
    },
    [LeagueTier.Legend]: {
        icon: "fluent-emoji-flat:crown",
        label: "Legend",
    },
}

/** Props for {@link LeagueTierBadge}. */
export interface LeagueTierBadgeProps {
    /** Which tier to render. */
    tier: LeagueTier
    /** Icon size in px (default 24). */
    size?: number
    /** Show the tier name next to the icon. */
    showLabel?: boolean
}

/**
 * Renders a weekly-league tier as its multicolor `fluent-emoji-flat` badge,
 * optionally with the tier name. Pure presentational ??? drives off {@link LeagueTier}.
 * @param props - {@link LeagueTierBadgeProps}
 */
export const LeagueTierBadge = ({
    tier,
    size = 24,
    showLabel = false}: LeagueTierBadgeProps) => {
    // resolve the icon + label for this tier
    const visual = TIER_VISUAL[tier]
    return (
        <div className={"shrink-0"}>
            <StackH
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                items={[
                    () => (
                        // real art from MinIO (badges/league/<tier>.png) once uploaded; until
                        // then fall back to the multicolor fluent-emoji placeholder
                        <BadgeImage
                            objectKey={`badges/league/${tier}.png`}
                            size={size}
                            alt={visual.label}
                            fallback={(
                                <Icon
                                    icon={visual.icon}
                                    width={size}
                                    height={size}
                                    aria-label={visual.label}
                                />
                            )}
                        />
                    ),
                    ...(showLabel ? [() => (
                        <span className="text-sm font-medium text-foreground">
                            {visual.label}
                        </span>
                    )] : []),
                ]}
            />
        </div>
    )
}

import React from "react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { StatPair } from "@/components/composites/stats/StatPair"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { UserJobReadinessBand } from "@/modules/api/graphql/queries/types/user-job-readiness"

/** Readiness band -> the `Chip` tone that reads correctly. */
const BAND_CHIP_TONE: Record<UserJobReadinessBand, ChipTone> = {
    needsWork: "default",
    building: "warning",
    jobReady: "success",
}

/** All display text, already localized by the connected `JobReadinessWidget`; a story passes i18n keys. */
export interface JobReadinessWidgetLabels {
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
    /** Empty-branch title ??? no purchased-course track has a snapshot yet. */
    emptyTitle: string
    /** Empty-branch supporting line. */
    emptyDescription: string
    /** "Capstone project" pillar-meter label. */
    trackCapstone: string
    /** "Mock interview" pillar-meter label. */
    trackInterview: string
    /** "CV" pillar-meter label. */
    trackCv: string
}

/** Props for {@link _JobReadinessWidget} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface JobReadinessWidgetProps {
    /** First load, nothing in hand ??? the whole widget shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no strongest track (no purchased course has a snapshot yet) ??? the empty message. */
    isEmpty?: boolean
    /** Truthy ??? the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ??? paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Strongest track's course title (its own depth card, never blended with other tracks). */
    courseTitle?: string
    /** Strongest track's own depth score (0???100). */
    depthScore?: number
    /** Strongest track's readiness band ??? drives the chip's tone. */
    band?: UserJobReadinessBand
    /** Already-translated band label (e.g. "Building"), paired with {@link band}. */
    bandLabel?: string
    /** Already-translated + interpolated foundation-percentile sentence. `undefined` ??? the row is skipped (course has no ranked percentile yet). */
    foundationPercentileText?: string
    /** Strongest track's capstone score, or `null` when not attempted (row omitted once settled). */
    capstoneScore?: number | null
    /** Strongest track's mock-interview score, or `null` when not attempted (row omitted once settled). */
    interviewScore?: number | null
    /** Strongest track's CV-review score, or `null` when not attempted (row omitted once settled). */
    cvScore?: number | null
    /** Fired when the single CTA is pressed ??? jumps to whichever pillar is still missing. */
    onCtaPress?: () => void
    /** Already-translated CTA label, paired with {@link onCtaPress}. `undefined` ??? every pillar is already attempted, no CTA renders. */
    ctaLabel?: string
    /** Every display string, already resolved by the connected file. */
    labels: JobReadinessWidgetLabels
}

/**
 * DashboardPage "My job readiness" self-widget ??? the presentational half of
 * {@link import("./index").JobReadinessWidget}: the growth-loop nudge for the
 * viewer's OWN job-readiness snapshot ??? a headline (strongest track's depth +
 * band, plus the global foundation percentile), its capstone/interview/CV
 * pillar bars (each rendered only when attempted), and a single CTA aimed at
 * whichever pillar is still missing (capstone ??? mock interview ??? CV).
 *
 * Deliberately never suggests buying another course to raise a score (see
 * `.workflows/00-INDEX.md` fairness model + WF-06 copy discipline) ??? the CTA
 * only ever points at completing real work on the track the learner already
 * owns. Content only ??? the parent `LabeledCard` supplies the frame.
 *
 * Three states in the fixed order error ??? loading ??? empty ??? content
 * (BLOCK-8): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty`, and otherwise the one tree renders with
 * `isSkeleton` threaded to every leaf so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` ??? the connected
 * `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link JobReadinessWidgetProps}
 */
export const _JobReadinessWidget = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    courseTitle,
    depthScore,
    band,
    bandLabel,
    foundationPercentileText,
    capstoneScore = null,
    interviewScore = null,
    cvScore = null,
    onCtaPress,
    ctaLabel,
    labels,
}: JobReadinessWidgetProps) => {
    // error beats a stale loading flag; empty only once settled (BLOCK-8) ??? the empty and error
    // surfaces are the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md ??6).
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty icon={ChartLineUpIcon} title={labels.emptyTitle} description={labels.emptyDescription} />
    }

    // Each row is a DATA condition ??? a pillar with no score, or a foundation percentile that was
    // never ranked, is omitted rather than zero-filled ??? except while shimmering, when every row
    // renders as a placeholder (same row component, same count shape, loading-and-skeleton.md ??1).
    const showFoundation = isSkeleton || foundationPercentileText !== undefined
    const showCapstone = isSkeleton || capstoneScore !== null
    const showInterview = isSkeleton || interviewScore !== null
    const showCv = isSkeleton || cvScore !== null
    const showCta = isSkeleton || (onCtaPress !== undefined && ctaLabel !== undefined)

    // Hoisted so the outer gap={4} column is gap-only (no nested `at` false-positive).
    // Step 4 vertical peers (score row ?? meters ?? CTA) have no fitting token ??? see ledger.
    const widgetItems = [
        () => (
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                at="sm" items={[
                    () => (isSkeleton
                        ? <StatPair isSkeleton />
                        : <StatPair value={String(depthScore ?? 0)} label={courseTitle ?? ""} />),
                    () => (isSkeleton
                        ? <Chip isSkeleton />
                        : <Chip tone={band ? BAND_CHIP_TONE[band] : "default"} text={bandLabel ?? ""} />),
                ]} />
        ),
        ...(showFoundation ? [() => (
            <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={foundationPercentileText} />
        )] : []),
        ...(showCapstone ? [() => (
            isSkeleton
                ? <ProgressMeter isSkeleton showValue label={labels.trackCapstone} />
                : <ProgressMeter value={capstoneScore ?? 0} max={100} showValue label={labels.trackCapstone} />
        )] : []),
        ...(showInterview ? [() => (
            isSkeleton
                ? <ProgressMeter isSkeleton showValue label={labels.trackInterview} />
                : <ProgressMeter value={interviewScore ?? 0} max={100} showValue label={labels.trackInterview} />
        )] : []),
        ...(showCv ? [() => (
            isSkeleton
                ? <ProgressMeter isSkeleton showValue label={labels.trackCv} />
                : <ProgressMeter value={cvScore ?? 0} max={100} showValue label={labels.trackCv} />
        )] : []),
        ...(showCta ? [() => (
            isSkeleton
                ? <Button isSkeleton variant="primary" classNames={["self-start"]} />
                : <Button variant="primary" classNames={["self-start"]} label={ctaLabel ?? ""} suffixIcon={ArrowRightIcon} onPress={onCtaPress} />
        )] : []),
    ]

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "JobReadinessWidget" }}
            items={widgetItems}
        />
    )
}

"use client"

import React from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH } from "@/components/frames/Stack"

/** Representative week columns shown (the real grid is ~53, draggable past the viewport). */
const WEEK_COLUMNS = 26

/** Rows per week column (Sun???Sat). */
const WEEK_ROWS = 7

/** Year-switcher button placeholders (current + 2 back). */
const YEAR_BUTTONS = 3

/**
 * Loading placeholder for {@link import("../").OverviewContributions}: mirrors the
 * {@link import("@/components/blocks/profile/ContributionCalendarView").ContributionCalendarView}
 * heatmap ??? header (count + year switcher), the 7??N cell grid, and the Less???More
 * legend ??? at the same cell size / gaps so the box does not jump when data resolves.
 *
 * @param props - {@link OverviewContributionsSkeleton}
 */
export const OverviewContributionsSkeleton = ({ className }: WithClassNames<undefined>) => {
    return (
        <div className={cn("flex flex-col gap-3", className)}>
            {/* header: count text (left) + year switcher (right) */}
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between" align="center" items={[
                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                    () => (
                        <StackH gap={3} principle="flex-action"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            align="center" items={
                                Array.from({ length: YEAR_BUTTONS }, (_, index) => () => (
                                    <Skeleton key={index} className="h-5 w-10 rounded-medium" />
                                ))
                            } />
                    ),
                ]} />

            {/* grid: weekday label column + N week columns of 7 cells ??? gap-[3px] is calendar cell pitch, not a house seam */}
            <div className="flex gap-[3px] overflow-hidden">
                <div className="w-8 shrink-0" />
                {Array.from({ length: WEEK_COLUMNS }).map((_, columnIndex) => (
                    <div key={columnIndex} className="flex shrink-0 flex-col gap-[3px]">
                        {Array.from({ length: WEEK_ROWS }).map((_cell, rowIndex) => (
                            <Skeleton key={rowIndex} className="size-3 shrink-0 rounded-sm" />
                        ))}
                    </div>
                ))}
            </div>

            {/* legend: Less ??? More (5 cells, right-aligned) */}
            <StackH gap={3} principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                justify="end" align="center" items={
                    Array.from({ length: 5 }, (_, index) => () => (
                        <Skeleton key={index} className="size-3 shrink-0 rounded-sm" />
                    ))
                } />
        </div>
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ContributionCalendarView } from "@/components/blocks/profile/ContributionCalendarView"
import { StackV } from "@/components/frames/Stack"
import type { CallerIdentity } from "@/components/frames/_identity"
import type { QueryMyContributionDayData } from "@/modules/api/graphql/queries/types/my-dashboard"

/** This block's own identity (BLOCK-2/split.md) ??? handed down to the track standing in as its root. See `_identity.ts`. */
const IDENTITY: CallerIdentity = { tier: "block", component: "OverviewContributions" }

/** All display text, already localized by the connected `OverviewContributions`; a story passes i18n keys. */
export interface OverviewContributionsLabels {
    errorTitle: string
    retry: string
}

/** Props for {@link _OverviewContributions} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface OverviewContributionsProps {
    /** First load, nothing in hand ??? the header/grid/legend shimmer in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy ??? the error message (beats loading). The connected file only passes its settled fetch error (no cached days left to show). */
    error?: unknown
    /** Retry handler ??? paired with `labels.retry`. */
    onRetry?: () => void
    /** Active contribution days for the selected year (oldest first); ignored while `isSkeleton`. */
    days?: Array<QueryMyContributionDayData>
    /** The year currently shown. */
    year: number
    /** Called with the picked year when the user flips the year switcher. */
    onYearChange: (year: number) => void
    labels: OverviewContributionsLabels
}

/**
 * DashboardPage contribution heatmap (GitHub-style) for the signed-in viewer ??? the presentational half
 * of {@link import("./index").OverviewContributions}. Content only (the parent
 * {@link import("@/components/blocks").LabeledCard} frames it). Two states in the fixed order
 * error ??? content (BLOCK-8; there is no genuine empty state ??? a zero-activity year still renders a
 * real, mostly-blank calendar, so `days.length === 0` is not "nothing to show"): `error` falls to
 * the shared `AsyncContentError` frame.
 *
 * {@link ContributionCalendarView} carries no `isSkeleton` prop of its own (`missingSkeletonSupport`
 * ??? it is a sibling component, not owned by this split), so while shimmering this swaps in a
 * minimal `Skeleton.*` mirror of its header (count line + year switcher) / grid / legend right here,
 * still co-located with the real tree instead of a separate skeleton file (`loading-and-skeleton.md`).
 * See `tiers/split.md` ??? the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link OverviewContributionsProps}
 */
export const _OverviewContributions = ({
    isSkeleton = false,
    error,
    onRetry,
    days = [],
    year,
    onYearChange,
    labels,
}: OverviewContributionsProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    // The calendar owns its own resting state, so this block hands the flag down instead
    // of keeping a second description of the same shape (`loading-and-skeleton.md`).
    return (
        <StackV
            gap={4}
            identity={IDENTITY}
            body={() => (
                <ContributionCalendarView
                    isSkeleton={isSkeleton}
                    days={days}
                    year={year}
                    onYearChange={onYearChange}
                />
            )}
        />
    )
}

