    const locale = useLocale()
    const router = useRouter()
    const username = useAppSelector((state) => state.user.user?.username)
    // spendable reward balance ??? surfaced as a chip on the rewards shortcut
    const { data: wallet } = useQueryMyRewardWalletSwr()
    // due-card count ??? a live "N due" nudge on the review shortcut
    const { data: dueFlashcards } = useQueryMyDueFlashcardsSwr()
    const dueCount = dueFlashcards?.dueCount ?? 0

    /** The shortcut rows (icon + label + destination), ordered by everyday frequency. */
    const actions = useMemo(
        () => [
            {
                key: "courses",
                Icon: GraduationCapIcon,
                href: pathConfig().locale(locale).course().build(),
            },
            {
                key: "review",
                Icon: CardsIcon,
                href: pathConfig().locale(locale).review().build(),
            },
            {
                key: "practice",
                Icon: CodeIcon,
                href: pathConfig().locale(locale).practice().build(),
            },
            {
                key: "league",
                Icon: TrophyIcon,
                href: pathConfig().locale(locale).league().build(),
            },
            {
                key: "bookmarks",
                Icon: BookmarkSimpleIcon,
                // bookmarks live under the viewer's own profile
                href: username
                    ? pathConfig().locale(locale).profile(username).bookmarks().build()
                    : pathConfig().locale(locale).course().build(),
            },
            {
                key: "rewards",
                Icon: GiftIcon,
                href: pathConfig().locale(locale).rewards().build(),
            },
            {
                key: "blog",
                Icon: ArticleIcon,
                href: pathConfig().locale(locale).blog().build(),
            },
            {
                key: "talents",
                Icon: UsersThreeIcon,
                href: pathConfig().locale(locale).talents().build(),
            },
            {
                key: "jobs",
                Icon: BriefcaseIcon,
                href: pathConfig().locale(locale).jobs().build(),
            },
        ],
        [
            locale,
            username,
        ],
    )

    // nav-on-activate: ListBox with no selection ??? onAction fires the item id; we
    // route to its href (Next client nav). Using the NATIVE HeroUI ListBox chrome
    // (react-aria) instead of hand-rolling a Link + hover class ??? the row highlight
    // (`data-[hovered=true]:bg-default`) is the component's own hover fill.
    const onAction = useCallback(
        (key: React.Key) => {
            const action = actions.find((item) => item.key === key)
            if (action) {
                router.push(action.href)
            }
        },
        [actions, router],
    )

    return (
        <LabeledList label={t("DashboardPage.quickActions")}>
            <ListBox
                aria-label={t("DashboardPage.quickActions")}
                selectionMode="none"
                onAction={onAction}
                className="p-0"
            >
                {actions.map(({
                    key,
                    Icon,
                }) => (
                    <ListBox.Item
                        key={key}
                        id={key}
                        textValue={t(`DashboardPage.actions.${key}`)}
                        // icon + label share the row's `text-foreground` (icon.md ??leading:
                        // leading icon same colour as its title, not a stray `text-muted`);
                        // hover fill is native ListBox chrome, no hand-rolled hover class.
                        // content-row: leading icon ?? label ?? trailing chip (retuned gap-3???gap-4).
                        className="flex cursor-pointer items-center gap-4 rounded-large px-2 py-2 text-foreground outline-none data-[focus-visible=true]:ring-2 data-[focus-visible=true]:ring-accent data-[hovered=true]:bg-default" data-principle="content-row"
                    >
                        <Icon aria-hidden focusable="false" className="size-5 shrink-0" />
                        <span className="min-w-0 flex-1 truncate text-sm">
                            {t(`DashboardPage.actions.${key}`)}
                        </span>
                        {key === "rewards" && wallet ? (
                            <Chip className="shrink-0" size="sm" variant="soft" color="warning">
                                <Chip.Label>
                                    {t("DashboardPage.rewardBalance", { count: wallet.balance })}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                        {key === "review" && dueCount > 0 ? (
                            // "due" = a backlog nudge ??? warning (amber), NOT accent
                            // (accent is reserved for brand/CTA). Matches the DeckList/StudyRail/QuizSession convention.
                            <Chip className="shrink-0" size="sm" variant="soft" color="warning">
                                <Chip.Label>
                                    {t("DashboardPage.dueCount", { count: dueCount })}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                    </ListBox.Item>
                ))}
            </ListBox>
        </LabeledList>
    )
}

import React from "react"
import {
    BookOpenIcon,
} from "@phosphor-icons/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import {
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import {
    Typography,
} from "@/components/atoms/text/Typography"
import {
    IconTile,
} from "@/components/blocks/identity/IconTile"
import {
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@/components/composites/cards/SurfaceCard"
import {
    Skeleton,
} from "@/components/blocks/skeleton/Skeleton"
import {
    PriceTagInline,
} from "@/components/blocks/commerce/PriceTag"
import {
    StackH,
    StackV,
} from "@/components/frames/Stack"

/** How many placeholder rows the co-located skeleton shows. */
const SKELETON_ROW_COUNT = 3

/** One recommended (not-yet-enrolled) course row, already resolved by the connected half. */
export interface RecommendedCoursesItem {
    /** Public display id ??? also the row's React key. */
    displayId: string
    title: string
    description: string | null
    thumbnailUrl: string | null
    /** Deep link into the course detail page, already locale-prefixed. */
    href: string
    /** Price the viewer actually pays (their loyalty discount already applied). */
    discountedPriceVnd: number
    originalPriceVnd: number
    /** `true` when the viewer's loyalty discount applies (`discountPercent > 0`). */
    discounted: boolean
    /** Already-translated "why this discount" line; omitted when there's no discount or no reason. */
    reasonText?: string
}

/** All display text, already localized by the connected `RecommendedCourses`. */
export interface RecommendedCoursesLabels {
    /** Section title above the card. */
    title: string
    /** Error-branch title. */
    loadErrorTitle: string
    /** Error-branch retry button label. */
    retry: string
}

/** Props for {@link _RecommendedCourses} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface RecommendedCoursesProps extends WithClassNames<undefined> {
    /** First load, nothing in hand ??? the list rows shimmer in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero recommendations ??? the whole section hides (nothing left to recommend). */
    isEmpty?: boolean
    /** Truthy ??? the error message (beats the empty hide). The connected file only forwards a settled error with nothing in hand. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Recommended courses, in display order. */
    items?: Array<RecommendedCoursesItem>
    labels: RecommendedCoursesLabels
}

/**
 * "Courses for you" ??? class A collapse: one {@link SurfaceCardList} owns label +
 * identity + isSkeleton + free-form course rows (B37). Former LabeledCard frameless
 * shell and SurfaceListCard children API removed.
 *
 * @param props - {@link RecommendedCoursesProps}
 */
export const _RecommendedCourses = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    items = [],
    labels,
}: RecommendedCoursesProps) => {
    if (!isSkeleton && !error && isEmpty) {
        return null
    }

    const listItems: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from(
            {
                length: SKELETON_ROW_COUNT,
            },
            (_unused, index) => ({
                key: `skeleton-${index}`,
                content: () => (
                    <StackH gap={3} items={[
                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                        () => (
                            <StackV gap={2} classNames={[
                                "min-w-0",
                                "flex-1",
                            ]} items={[
                                () => <Typography size="sm" weight="medium" isSkeleton />,
                                () => <Skeleton.Typography type="body-xs" width="1/4" />,
                            ]} />
                        ),
                    ]} />
                ),
            }),
        )
        : items.map((course) => ({
            key: course.displayId,
            href: course.href,
            hover: "underline" as const,
            content: () => (
                <StackH gap={3} items={[
                    () => (
                        <IconTile
                            size="sm"
                            src={course.thumbnailUrl}
                            alt={course.title}
                            icon={<BookOpenIcon aria-hidden focusable="false" />}
                        />
                    ),
                    () => (
                        <StackV gap={1} classNames={[
                            "min-w-0",
                            "flex-1",
                        ]} items={[
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    truncate
                                    underlineOnGroupHover
                                    text={course.title}
                                />
                            ),
                            ...(course.description ? [
                                () => (
                                    <Typography size="xs" color="muted" truncate text={course.description} />
                                ),
                            ] : []),
                            () => (
                                <PriceTagInline
                                    discounted={course.discountedPriceVnd}
                                    original={course.discounted ? course.originalPriceVnd : null}
                                />
                            ),
                            ...(course.reasonText ? [
                                () => (
                                    <Typography size="xs" color="accent-soft" text={course.reasonText} />
                                ),
                            ] : []),
                        ]} />
                    ),
                ]} />
            ),
        }))

    return (
        <SurfaceCardList
            identity={{
                tier: "block",
                component: "RecommendedCourses",
            }}
            label={labels.title}
            items={listItems}
            isSkeleton={isSkeleton}
            error={error}
            errorState={() => (
                <AsyncContentError
                    title={labels.loadErrorTitle}
                    onRetry={onRetry}
                    retryLabel={labels.retry}
                />
            )}
        />
    )
}

import React from "react"
import {
    SnowflakeIcon,
} from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"

/** Maximum number of streak freezes a user may own. */
export const MAX_FREEZES = 3

/** Points cost of one streak freeze. */
export const FREEZE_COST = 100

/** All display text, already localized by the connected `StreakFreezeCard`; a story passes i18n keys. */
export interface StreakFreezeCardLabels {
    title: string
    errorTitle: string
    retry: string
    /** Already interpolated with the owned count and {@link MAX_FREEZES} (e.g. "2 of 3"). */
    owned: string
    explainer: string
    /** Already interpolated with {@link FREEZE_COST} (e.g. "Buy for 100 points"). */
    buy: string
    full: string
}

/** Props for {@link _StreakFreezeCard} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface StreakFreezeCardProps {
    /** First load, nothing in hand ??? the whole card shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no data (signed out / genuinely unavailable) ??? the card self-hides. */
    isEmpty?: boolean
    /**
     * Truthy ??? the error message (beats loading + empty). The connected file only passes its
     * settled fetch error when there is no cached data left to fall back to.
     */
    error?: unknown
    /** Retry handler ??? paired with `labels.retry`. */
    onRetry?: () => void
    /** How many freezes the viewer currently owns. */
    owned?: number
    /** `true` while the purchase mutation is in flight. */
    buying?: boolean
    /** Fired when the learner presses "Buy". */
    onBuy?: () => void
    labels: StreakFreezeCardLabels
}

/**
 * Right-rail "streak freeze" card ??? the presentational half of {@link StreakFreezeCard}. A freeze
 * keeps the daily streak alive when the viewer misses a single day; shows how many they own (of
 * {@link MAX_FREEZES}) and a "buy for {@link FREEZE_COST} points" trigger. Four states in the fixed
 * order error ??? loading ??? empty ??? content (BLOCK-8): a settled `error` falls to the shared
 * `AsyncContentError` frame with no card shell around it (a stale card beats a scary error, but an
 * error replaces the card rather than living inside it); `isEmpty` self-hides entirely (no
 * `emptyContent` ??? matches the sibling right-rail widgets); otherwise the owned line, explainer, and
 * buy button render inside `SectionCard`, with `isSkeleton` threaded to every leaf so the shimmer
 * mirrors the loaded shape. See `tiers/split.md` ??? the connected `index.tsx` owns the fetch, the
 * `buyStreakFreeze` mutation, and i18n.
 *
 * @param props - {@link StreakFreezeCardProps}
 */
export const _StreakFreezeCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    owned = 0,
    buying = false,
    onBuy,
    labels,
}: StreakFreezeCardProps) => {
    // error ??? skeleton ??? empty ??? content (BLOCK-8): error beats a stale loading flag.
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return null
    }

    const full = owned >= MAX_FREEZES

    return (
        <SectionCard
            icon={() => <SnowflakeIcon className="size-5 text-accent-soft-foreground" />}
            title={labels.title}
        >
            <Typography
                size="sm"
                weight="medium"
                text={labels.owned}
                isSkeleton={isSkeleton}
            />
            <Typography
                size="xs"
                color="muted"
                text={labels.explainer}
                isSkeleton={isSkeleton}
                classNames={isSkeleton ? ["w-full"] : undefined}
            />
            {isSkeleton ? (
                <Button isSkeleton variant="tertiary" size="sm" />
            ) : (
                <Button
                    variant="tertiary"
                    size="sm"
                    isDisabled={full || buying}
                    isPending={buying}
                    label={full ? labels.full : labels.buy}
                    onPress={onBuy}
                />
            )}
        </SectionCard>
    )
}

import React from "react"
import { CircleIcon, FlameIcon } from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { InfoTooltip } from "@/components/blocks/feedback/InfoTooltip"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Split } from "@/components/frames/Split"
import type { CallerIdentity } from "@/components/frames/_identity"

/** How many placeholder day-dots the co-located skeleton shows (last 7 days, always seven). */
const SKELETON_DAY_COUNT = 7

/** This block's own identity (BLOCK-2/split.md) ??? handed down to the root `StackV`. See `_identity.ts`. */
const IDENTITY: CallerIdentity = { tier: "block", component: "StreakStrip" }

/** One of the last 7 days, already resolved by the connected `StreakStrip` (locale formatting is i18n ??? it stays in `index.tsx`). */
export interface StreakStripDay {
    /** ISO date (`YYYY-MM-DD`) ??? used only as the React key. */
    date: string
    /** Whether the learner was active this day. */
    active: boolean
    /** Already-locale-formatted full date, shown as the dot's native tooltip. */
    title: string
    /** Already-locale-formatted narrow weekday label under the dot. */
    weekday: string
}

/** All display text, already localized by the connected `StreakStrip`; a story passes i18n keys. */
export interface StreakStripLabels {
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
    /** `InfoTooltip` heading over the current-streak readout. */
    streakLabel: string
    /** `InfoTooltip` explanation under {@link StreakStripLabels.streakLabel}. */
    streakHelp: string
    /** Current-streak sentence, already interpolated with the day count. */
    current: string
    /** Longest-streak chip label, already interpolated with the day count. */
    longest: string
    /** "No streak yet" message shown when there is nothing to show off. */
    empty: string
    /** Daily-goal CTA label ??? shared by the empty state and the idle-today nudge. */
    dailyGoalCta: string
    /** Idle-today nudge sentence ("keep the streak alive"). */
    dailyGoalNudge: string
}

/** Props for {@link _StreakStrip} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface StreakStripProps {
    /** First load, nothing in hand ??? the whole strip shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy ??? the error message (beats loading). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ??? paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Current streak length, in days. */
    streak?: number
    /** Longest streak ever reached, in days. */
    /** The last 7 days, oldest first. */
    days?: Array<StreakStripDay>
    /** Fired by both daily-goal CTAs (empty state + idle-today nudge) ??? jumps to the course list. */
    onLearn?: () => void
    labels: StreakStripLabels
}

/**
 * "Learning streak" content ??? the presentational half of {@link StreakStrip}: the last-7-days dot
 * strip plus current/longest streak, and a daily-goal nudge when today is still idle. Content only
 * (the parent {@link import("@/components/blocks").LabeledCard} frames it). Two states in the fixed
 * order error ??? content (BLOCK-8): `error` falls to the shared `AsyncContentError` frame ??? there is
 * no genuine empty-fetch state, only the domain "no streak yet" message that renders inline, in place
 * of the flame/chip cluster, once settled; otherwise the strip renders with `isSkeleton` threaded to
 * every leaf so the shimmer mirrors the loaded shape. The day dot (`CircleIcon`) and the streak
 * readout (`InfoTooltip`) carry no `isSkeleton` of their own, so each is mirrored right where it sits
 * with a bare `Skeleton`/`Skeleton.Typography` (loading-and-skeleton.md ??1). See `tiers/split.md` ???
 * the connected `index.tsx` owns the fetch, the router, and the locale-formatted day labels.
 *
 * @param props - {@link StreakStripProps}
 */
export const _StreakStrip = ({
    isSkeleton = false,
    error,
    onRetry,
    streak = 0,
    days = [],
    onLearn,
    labels,
}: StreakStripProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    // "has anything to show off" ??? a real streak day, or a currently-running streak. The flame/chip
    // cluster renders optimistically while shimmering (the eventual value isn't known yet); once
    // settled, a learner with nothing yet sees the empty message + CTA instead.
    const hasActivity = streak > 0 || days.some((day) => day.active)
    const showActiveCluster = isSkeleton || hasActivity
    const activeToday = days.at(-1)?.active === true
    const showNudge = !isSkeleton && hasActivity && !activeToday

    // day-dot column ??? while shimmering, 7 placeholder columns keep the SAME shape (loading-and-skeleton.md
    // ??1: same leaf, same count). `CircleIcon` has no `isSkeleton` of its own, so the mirror sits right
    // here, co-located, rather than in a parallel tree.
    const dayItems: Array<ComponentTypeWithSkeleton> = isSkeleton
        ? Array.from({ length: SKELETON_DAY_COUNT }, () => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => <Skeleton className="size-6 shrink-0 rounded-full" />,
                    () => <Typography isSkeleton size="xs" />,
                ]} />
        ))
        : days.map((day) => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => (
                    // No `title`: the dot is `aria-hidden`, so a tooltip string on it would be
                    // announced to nobody ??? the weekday label below carries the meaning.
                        <CircleIcon
                            aria-hidden
                            focusable="false"
                            weight="fill"
                            className={day.active ? "size-6 shrink-0 text-accent/80" : "size-6 shrink-0 text-muted/20"}
                        />
                    ),
                    () => <Typography size="xs" color="muted" text={day.weekday} />,
                ]} />
        ))

    return (
        <StackV gap={4} isSkeleton={isSkeleton} identity={IDENTITY} items={[
            () => (
                <Split gap={4} isSkeleton={isSkeleton}
                    start={() => <Cluster gap={3} isSkeleton={isSkeleton} items={dayItems} />}
                    end={() => (
                        showActiveCluster ? (
                            <StackH gap={3} isSkeleton={isSkeleton} items={[
                                () => (
                                    isSkeleton
                                        ? <Skeleton className="size-5 shrink-0 rounded-full" />
                                        : <FlameIcon aria-hidden focusable="false" className="size-5 shrink-0 text-accent-soft-foreground" />
                                ),
                                () => (
                                    isSkeleton
                                        ? <Skeleton.Typography type="body-sm" width="1/4" />
                                        : (
                                            <InfoTooltip className="text-sm font-medium" title={labels.streakLabel} description={labels.streakHelp}>
                                                {labels.current}
                                            </InfoTooltip>
                                        )
                                ),
                                () => <Chip isSkeleton={isSkeleton} tone="accent" text={labels.longest} />,
                            ]} />
                        ) : (
                            <StackH gap={4} items={[
                                () => <Typography size="sm" color="muted" text={labels.empty} />,
                                () => <Button variant="primary" size="sm" onPress={onLearn} label={labels.dailyGoalCta} />,
                            ]} />
                        )
                    )}
                />
            ),
            ...(showNudge ? [() => (
                <Split gap={4}
                    start={() => <Typography size="sm" weight="medium" text={labels.dailyGoalNudge} />}
                    end={() => <Button variant="primary" size="sm" onPress={onLearn} label={labels.dailyGoalCta} />}
                />
            )] : []),
        ]} />
    )
}

import React from "react"
import {
    VideoCameraIcon,
} from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Typography } from "@/components/atoms/text/Typography"

/** How many upcoming sessions to list (the soonest plus a few more). */
export const MAX_ROWS = 3

/** One resolved upcoming-livestream row, already localized by the connected `UpcomingLivestreamCard`. */
export interface UpcomingLivestreamCardSession {
    /** Stable row key ??? a course can carry more than one upcoming session. */
    key: string
    /** Row title ??? the session title, falling back to the course title. */
    title: string
    /** Row subtitle ??? the course title, shown only when the title above is the session's own. */
    subtitle?: string
    /** Already-formatted relative countdown ("in Nd Nh" / "in Nh Nm" / "now"). */
    relativeLabel: string
    /** Already-formatted absolute date, in the viewer's locale. */
    dateLabel: string
    /** Course page to navigate to on press. */
    href: string
}

/** All display text, already localized by the connected `UpcomingLivestreamCard`. */
export interface UpcomingLivestreamCardLabels {
    /** Card header title. */
    title: string
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
}

/** Props for {@link _UpcomingLivestreamCard} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface UpcomingLivestreamCardProps {
    /** First load, nothing in hand ??? the whole row list shimmers in place. Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with nothing upcoming ??? the card hides itself entirely (no emptyContent ??? matches the sibling right-rail widgets, e.g. `WhoToFollow`). */
    isEmpty?: boolean
    /** Truthy ??? the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ??? paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** The soonest few sessions, already sorted, capped, and formatted. */
    sessions?: Array<UpcomingLivestreamCardSession>
    labels: UpcomingLivestreamCardLabels
}

/**
 * Right-rail card surfacing the viewer's next live sessions across enrolled courses
 * (soonest first), so a scheduled stream is visible from the home surface instead of
 * buried in a course page ??? the presentational half of `UpcomingLivestreamCard`. The
 * soonest session leads with a relative countdown ("in Nd Nh"); a short list of the
 * next few follows. Three states in the fixed order error ??? loading ??? empty ???
 * content (BLOCK-8): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * hides the card (no emptyContent, matching the sibling right-rail widgets that
 * self-hide rather than render an empty state), and otherwise the row list renders ???
 * while shimmering, `Skeleton.ListRow` placeholders keep the SAME `SectionCard` +
 * `SurfaceCardList` shape so the box neither shrinks nor jumps when data arrives
 * (loading-and-skeleton.md). See `tiers/split.md` ??? the connected `index.tsx` owns
 * the fetch and i18n.
 *
 * @param props - {@link UpcomingLivestreamCardProps}
 */
export const _UpcomingLivestreamCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    sessions = [],
    labels,
}: UpcomingLivestreamCardProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return null
    }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from(
        { length: MAX_ROWS },
        (_unused, index) => ({
            key: `skeleton-${index}`,
            content: () => (
                <Box
                    principle="row-pad"
                    explain="Row content inset ??? not cell-pad, because this pads a horizontal content row rather than a dense table cell."
                >
                    <Skeleton.ListRow withSubtitle />
                </Box>
            ),
        }),
    )

    const sessionItems: Array<SurfaceCardListItem> = sessions.map((session) => ({
        key: session.key,
        leading: () => <IconTile icon={<VideoCameraIcon />} tone="accent" size="sm" />,
        title: session.title,
        subtitle: session.subtitle,
        meta: () => (
            <Typography
                size="xs"
                weight="medium"
                color="accent-soft"
                text={`${session.relativeLabel} ?? ${session.dateLabel}`}
            />
        ),
        href: session.href,
    }))

    return (
        <SectionCard
            icon={() => <VideoCameraIcon className="size-5 text-accent-soft-foreground" />}
            title={labels.title}
        >
            <SurfaceCardList
                variant="nested"
                items={isSkeleton ? skeletonItems : sessionItems}
            />
        </SectionCard>
    )
}

