                        </SurfaceListCard>
                    ),
                ]} />
        </LabeledCard>
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { StatGridCard, type StatGridCardItem } from "@/components/composites/stats/StatGridCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { KPI_ICON_MAP } from "@/modules/utils/weekly-goals-map"
import type { KpiKey } from "@/modules/api/graphql/queries/types/my-kpis"

/** One weekly-metric row, already resolved by the connected {@link import("./index").WeeklyGoals}. */
export interface WeeklyGoalsItem {
    /** Which weekly metric this row is. */
    key: KpiKey
    /** Already-localized metric label. */
    label: string
    /** This week's value so far. */
    current: number
    /** Effective target ??? the learner's custom goal, or the sensible default. */
    target: number
    /** Already-localized coin-reward hint; omitted when no target is set server-side. */
    coinRewardText?: string
    /** `true` ??? this metric's reward can be claimed right now. */
    canClaim: boolean
}

/** All display text, already localized by the connected `WeeklyGoals`; a story passes i18n keys. */
export interface WeeklyGoalsLabels {
    /** Title on the error branch. */
    errorTitle: string
    /** Retry-button label, paired with `onRetry`. */
    retry: string
}

/** Props for {@link _WeeklyGoals} ??? presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyGoalsProps {
    /** First load, nothing in hand ??? the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy ??? the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** All six weekly metrics, in display order. No empty state ??? this is always the fixed six-metric set. */
    items: Array<WeeklyGoalsItem>
    /** The composite summary sentence (percent/completed/total, plus the reset countdown when known), already interpolated. */
    summaryText?: string
    labels: WeeklyGoalsLabels
}

/**
 * One metric cell's content: a `ProgressMeter` carrying the icon+label / ratio row in its own
 * `leading`/`trailing` slots (same idiom as the sibling `AiQuotaCard` block), then an optional
 * coin-reward hint below it.
 */
const renderGoalCell = (item: WeeklyGoalsItem, isSkeleton: boolean) => (
    <StackV gap={3} principle="sibling-stack"
        explain="Same-kind peer stack ??? not group-boundary, because these items are repeating siblings rather than section groups."
        isSkeleton={isSkeleton} items={[
        // ATOM GAP: `ProgressMeter`'s discriminated `isSkeleton` union needs a literal branch
        // to narrow at compile time ??? a runtime boolean can't satisfy it directly.
            () => (isSkeleton
                ? (
                    <ProgressMeter
                        isSkeleton
                        leading={() => <Typography size="sm" prefixIcon={KPI_ICON_MAP[item.key]} isSkeleton text={item.label} />}
                        trailing={() => <Typography size="xs" color="muted" tabularNums isSkeleton text={`${item.current}/${item.target}`} />}
                    />
                )
                : (
                    <ProgressMeter
                        value={item.current}
                        max={item.target > 0 ? item.target : 1}
                        color="accent"
                        leading={() => <Typography size="sm" prefixIcon={KPI_ICON_MAP[item.key]} text={item.label} />}
                        trailing={() => <Typography size="xs" color="muted" tabularNums text={`${item.current}/${item.target}`} />}
                    />
                )),
            // coin-reward hint ??? only once a REAL target is set server-side, and never while
            // shimmering (unknown yet whether this row will show one ??? same as the loaded shape
            // it mirrors, `WeeklyGoalsProps.items` never carries a reward while `isSkeleton`).
            ...(!isSkeleton && item.coinRewardText ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent-soft" : "muted"}
                    text={item.coinRewardText}
                />
            )] : []),
        ]} />
)

/**
 * "Weekly goals" content ??? the presentational half of {@link import("./index").WeeklyGoals}: the
 * composite weekly-goal summary + a per-metric breakdown (lessons / study-days / challenges /
 * coding / flashcards / milestones), each with a progress meter against its effective target.
 * Content only ??? the caller's `LabeledCard` frames it.
 *
 * `error` beats a stale loading flag (BLOCK-8): it falls to the shared `AsyncContentError` frame,
 * otherwise the fixed six-metric tree renders with `isSkeleton` threaded to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md). No `isEmpty` state ??? `items` is
 * always the fixed six-metric set, so there is nothing to be empty. See `tiers/split.md` ??? the
 * connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
export const _WeeklyGoals = ({
    isSkeleton = false,
    error,
    onRetry,
    items,
    summaryText,
    labels,
}: WeeklyGoalsProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }

    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => renderGoalCell(item, isSkeleton),
    }))

    return (
        <StackV gap={3} isSkeleton={isSkeleton} identity={{ tier: "block", component: "WeeklyGoals" }} items={[
            () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={summaryText} />,
            () => <StatGridCard items={gridItems} />,
        ]} />
    )
}

import React from "react"
import Link from "next/link"
import {
    UserPlusIcon,
} from "@phosphor-icons/react"
import {
    FollowButton,
} from "@/components/blocks/community/FollowButton"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Chip } from "@/components/atoms/chips/Chip"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV, StackH } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Placeholder row count shown while the first suggestion load is in flight. */
const SKELETON_ROW_COUNT = 4

/** One suggested-user row, already resolved by the connected `index.tsx`. */
export interface WhoToFollowUserItem {
    /** Stable identity; also the id forwarded to {@link WhoToFollowProps.onFollow}. */
    globalId: string
    /** Account username; drives the avatar fallback and the profile link target. */
    username: string
    /** Human-friendly name; `UserCell` falls back to {@link WhoToFollowUserItem.username}. */
    displayName?: string
    /** Uploaded avatar URL, resolved fallbacks handled by `UserCell`. */
    avatar?: string | null
    /** True ??? the row shows the "open to work" badge. */
    openToWork: boolean
    /** Fully-resolved, locale-aware link to this user's public profile. */
    profileHref: string
    /** True once the viewer has followed this user from this card (optimistic). */
    following: boolean
    /** True while this row's own follow request is in flight. */
    isPending: boolean
}

/** Props for {@link _WhoToFollow}. */
export interface WhoToFollowProps {
    /** Card title (already translated). */
    title: string
    /** "Open to work" badge label (already translated). */
    openToWorkLabel: string
    /** Suggested users, in display order. */
    users: ReadonlyArray<WhoToFollowUserItem>
    /** Follow a suggested user; the connected half owns the mutation and the optimistic state. */
    onFollow: (globalId: string) => void
    /** True on the first load, nothing to show yet. */
    isSkeleton?: boolean
    /** True once loaded with no suggestions at all. */
    isEmpty?: boolean
}

/** Props for the row {@link WhoToFollowRow} draws, real or shimmering. */
interface WhoToFollowRowProps {
    /** Resolved row data; omitted while {@link WhoToFollowRowProps.isSkeleton}. */
    user?: WhoToFollowUserItem
    /** "Open to work" badge label (already translated). */
    openToWorkLabel: string
    /** Follow a suggested user. */
    onFollow: (globalId: string) => void
    /** True ??? render the shimmer mirror instead of the live row. */
    isSkeleton?: boolean
}

/**
 * One suggestion row: [avatar ?? name + @handle (+ open-to-work badge)] on the
 * left, the follow toggle on the right. Mirrors its own shimmer through the
 * house `Skeleton.UserCell` / `Skeleton.Button` pieces so the row never jumps
 * when the real data arrives.
 */
const WhoToFollowRow = ({
    user,
    openToWorkLabel,
    onFollow,
    isSkeleton = false,
}: WhoToFollowRowProps) => (
    // padding-plus-gap: outer control-pad owns the inset; inner content-row owns the seam
    <Box principle="control-pad" className="px-3 py-2"
        explain="Control hit-area inset ??? not row-pad, because this pads a single interactive control rather than a full content row.">
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => (isSkeleton || !user ? (
                    <Skeleton.UserCell className="min-w-0 flex-1" />
                ) : (
                    <Link href={user.profileHref} className="min-w-0 flex-1">
                        <UserCell
                            username={user.username}
                            displayName={user.displayName}
                            avatar={user.avatar}
                            handle={`@${user.username}`}
                            trailing={user.openToWork
                                ? () => <Chip tone="success" text={openToWorkLabel} />
                                : undefined}
                        />
                    </Link>
                )),
                () => (isSkeleton || !user ? (
                    <Skeleton.Button className="shrink-0" />
                ) : (
                    <FollowButton
                        following={user.following}
                        isPending={user.isPending}
                        onToggle={() => {
                            // already followed from this card ??? no-op
                            if (!user.following) {
                                onFollow(user.globalId)
                            }
                        }}
                    />
                )),
            ]}
        />
    </Box>
)

/**
 * `_WhoToFollow` ??? the presentational half of `WhoToFollow` (see `./index.tsx`
 * for the connected half). Right-rail "who to follow" card listing users the
 * backend suggests, so the social graph keeps growing from the home surface.
 * Each row links to the user's public profile and carries a follow button that
 * fires {@link WhoToFollowProps.onFollow} (the connected half owns the
 * `setFollow` mutation and the optimistic "following" state).
 *
 * Renders ONE tree: `isSkeleton` threads straight down to `WhoToFollowRow`,
 * which shimmers via `Skeleton.UserCell` / `Skeleton.Button` instead of
 * building a second layout to keep in sync. Hides entirely once loaded with
 * nothing to suggest ??? same as before the split, no visible empty state.
 *
 * @param props - {@link WhoToFollowProps}
 */
export const _WhoToFollow = ({
    title,
    openToWorkLabel,
    users,
    onFollow,
    isSkeleton = false,
    isEmpty = false,
}: WhoToFollowProps) => {
    if (!isSkeleton && isEmpty) {
        return null
    }

    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, () => () => (
            <WhoToFollowRow openToWorkLabel={openToWorkLabel} onFollow={onFollow} isSkeleton />
        ))
        : users.map((user) => () => (
            <WhoToFollowRow user={user} openToWorkLabel={openToWorkLabel} onFollow={onFollow} />
        ))

    return (
        <SectionCard
            icon={() => <UserPlusIcon className="size-5 text-accent-soft-foreground" />}
            title={title}
        >
            <StackV gap={3} items={rows} />
        </SectionCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useDashboardTabUrlSync,
} from "@/hooks/useDashboardTabUrlSync"
import {
    DashboardTabsBar,
} from "./DashboardTabsBar"
import {
    DashboardIdentity,
} from "./DashboardIdentity"
import {
    OverviewTab,
} from "./OverviewTab"
import {
    ExploreTab,
} from "./ExploreTab"
import {
    CoursesTab,
} from "./CoursesTab"
import {
    CommunityTab,
} from "./CommunityTab"
import { useDashboardTabStore } from "@/hooks/zustand/dashboardTab/store"
import { useRegisterNavbarBottomLayer } from "@/hooks/zustand/navbarBottomLayer/store"
import { Container } from "@/components/frames/Container"
import { RailShell } from "@/components/frames/RailShell"

/** Props for {@link DashboardPage}. */
export type DashboardPageProps = Record<string, never>
/**
 * Logged-in home ??? rebuilt on the proven PROFILE page layout: a tab strip rendered
 * as the navbar's bottom layer, then a centered 2-column body ??? left = the viewer's identity +
 * standing (bare, stable across tabs), right = the selected tab's content. Tabs:
 * Overview (cockpit) ?? Explore (feed) ?? Courses ?? Community. The open tab lives in
 * the shared store and mirrors `?tab=` (shareable); only the active panel mounts,
 * so each tab's leaf queries fetch lazily. Mobile stacks the identity then the
 * content (no rail, no drawer). `"use client"` for the tab store + URL sync.
 * @param props - optional className for the root element
 */
export const DashboardPage = () => {
    useDashboardTabUrlSync()
    const tab = useDashboardTabStore((state) => state.tab)
    // the DashboardPage tab strip renders as the global Navbar's bottom layer
    const tabsNode = useMemo(() => <DashboardTabsBar />, [])
    useRegisterNavbarBottomLayer(tabsNode)

    // RailShell owns the identity<->content layout seam (stack -> row at md, gap-8).
    const rail = () => <DashboardIdentity />
    const body = () => {
        if (tab === "overview") {
            return (
                <div
                    id="DashboardPage-panel-overview"
                    role="tabpanel"
                    aria-labelledby="overview"
                >
                    <OverviewTab />
                </div>
            )
        }
        if (tab === "explore") {
            return (
                <div
                    id="DashboardPage-panel-explore"
                    role="tabpanel"
                    aria-labelledby="explore"
                >
                    <ExploreTab />
                </div>
            )
        }
        if (tab === "courses") {
            return (
                <div
                    id="DashboardPage-panel-courses"
                    role="tabpanel"
                    aria-labelledby="courses"
                >
                    <CoursesTab />
                </div>
            )
        }
        if (tab === "community") {
            return (
                <div
                    id="DashboardPage-panel-community"
                    role="tabpanel"
                    aria-labelledby="community"
                >
                    <CommunityTab />
                </div>
            )
        }
        return null
    }

    return (
        <div className={"flex w-full flex-col"}>
            {/* tab strip is registered as the Navbar bottom layer above (not here) */}
            <Container
                size="xl"
                padding={6}
                identity={{ tier: "block", component: "DashboardPage" }}
                body={() => (
                    <RailShell
                        at="md"
                        principle="layout-split"
                        explain="Major layout split ??? not block-boundary, because this separates primary page regions rather than adjacent blocks."
                        rail={rail}
                        body={body}
                    />
                )}
            />
        </div>
    )
}
